INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1232', 'spa', 'dar a conocer, declarar, anunciar; hablar públicamente sobre algo', 'Verbo compuesto que significa dar a conocer algo ampliamente o declararlo de forma pública. Su construcción básica implica anunciar algo (τί) a alguien (τινι). El verbo enfatiza el carácter público o exhaustivo de la comunicación: no se trata de una mención pasajera, sino de hacer algo plenamente conocido. En el uso neotestamentario, describe a los pastores proclamando públicamente lo que habían presenciado. La composición del verbo sugiere una declaración que trasciende la conversación privada y busca una difusión más amplia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1233', 'spa', 'decisión judicial, audiencia formal; examen o determinación oficial, especialmente en contextos legales', 'Este término designa el proceso de examen minucioso, discernimiento o toma de decisiones, particularmente en el ámbito judicial. En Acts 25:21 se emplea para referirse al caso de Pablo, reservado para la «decisión» o audiencia del emperador. En el griego clásico se usaba para el diagnóstico médico, el discernimiento filosófico o la determinación de valor. En el Nuevo Testamento predomina el contexto legal, como lo reflejan las traducciones uniformemente judiciales del término.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1234', 'spa', 'murmurar, quejarse entre sí; expresar descontento en voz baja', 'Este verbo compuesto intensifica el sentido básico de ''murmurar'' con un prefijo que sugiere exhaustividad o distribución—murmurar entre o a través de un grupo. Lucas lo usa dos veces para describir la reacción negativa de los fariseos y escribas ante las asociaciones de Jesús: murmurando porque él recibe a los pecadores y come con ellos (15:2), y murmurando porque ha ido a hospedarse con un pecador (19:7). El término evoca la imagen de susurros de desaprobación extendiéndose por una multitud, reflejando descontento comunal expresado en voz baja en lugar de confrontación abierta. El español ''murmuraban'' y el francés ''murmurer'' capturan este sentido de queja moderada pero generalizada.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1235', 'spa', 'despertar completamente, alcanzar plena vigilia; pasar del sueño o la somnolencia a la conciencia total', 'Este verbo compuesto intensifica el simple «despertar», subrayando un despertar completo y pleno. En Luke 9:32, Pedro, Santiago y Juan, aunque cargados de sueño, «despertaron plenamente» para presenciar la transfiguración de Cristo. El prefijo indica no un mero sobresalto, sino el logro de una alerta total. Se trata de la transición desde la pesadez del sueño hasta la conciencia y percepción completas, no solo abrir los ojos sino alcanzar plena lucidez.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1236', 'spa', 'llevar, pasar o transcurrir la vida de cierta manera; vivir a través del tiempo, conducir la vida', 'Este verbo combina movimiento (''conducir a través'') con duración temporal para expresar cómo uno conduce o pasa su vida. Los usos del Nuevo Testamento se enfocan en vivir pacífica y piadosamente: orando por las autoridades para que podamos ''llevar una vida tranquila y pacífica'' (1 Timoteo 2:2), y recordando cómo una vez pasamos nuestros días en malicia y envidia (Tito 3:3). El término enfatiza no la mera existencia sino la calidad y manera en que se lleva la vida. Las traducciones reflejan esto con ''pasar'' (español ''pasemos''), ''lead'' (inglés), y ''spend'' (alemán ''verbringen''), todas sugiriendo el paso intencional del tiempo en un estado o condición particular.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1237', 'spa', 'recibir en sucesión, suceder a otro; asumir por herencia o relevo una posición o posesión', 'Este verbo describe el acto de recibir algo que se transmite de otro, especialmente por sucesión o herencia. En Acts 7:45 se refiere a Josué y quienes «recibieron en sucesión» la tierra prometida después de Moisés. En el uso clásico abarcaba la sucesión al trono, la herencia de la dirección de escuelas filosóficas o la asunción del cargo de otro. La noción de transferencia secuencial es central en el significado de este término: una generación entrega a la siguiente lo que ella misma recibió.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1238', 'spa', 'Diadema, banda real o corona que simboliza soberanía y realeza', 'La diadema era una banda o cinta distintiva que se llevaba alrededor de la cabeza como símbolo de autoridad real. A diferencia del στέφανος (corona de victoria o festiva), la diadema señalaba específicamente el poder monárquico. En los contextos persa y helenístico, distinguía a los reyes del resto de la nobleza. En la imaginería apocalíptica del Apocalipsis, las diademas aparecen sobre las cabezas del dragón, la bestia del mar y Cristo conquistador, representando en cada caso pretensiones de soberanía y poder. La diadema no es meramente decorativa, sino símbolo del derecho a gobernar.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1239', 'spa', 'διαδίδωμι — distribuir, repartir o compartir entre varios destinatarios', 'διαδίδωμι es un verbo compuesto (διά + δίδωμι, ''dar a través de'') que significa distribuir o repartir entre múltiples destinatarios. Sus cuatro apariciones en el Nuevo Testamento implican siempre el reparto de bienes o recursos. Jesús ordena a un gobernante vender y distribuir a los pobres (Lc 18:22); los panes y los peces se reparten entre la multitud sentada (Jn 6:11); los primeros creyentes comparten sus posesiones según la necesidad de cada uno (Hch 4:35); y los despojos se dividen tras vencer al hombre fuerte (Lc 11:22). El verbo enfatiza un reparto sistemático y equitativo, no un dar casual.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1240', 'spa', 'sucesor; quien sigue a otro en un cargo o posición oficial', 'Este sustantivo designa a quien sucede a otro en un cargo, posición o responsabilidad. En Acts 24:27 se menciona que Félix fue sucedido por Porcio Festo como gobernador. El término podía referirse a la sucesión en el mando militar, en cargos políticos o en escuelas filosóficas. El concepto fundamental es el de una persona que reemplaza a otra en una función oficial. Todas las principales traducciones convergen en el significado de «sucesor», confirmando la univocidad semántica del vocablo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1241', 'spa', 'Ceñirse, envolverse alrededor de la cintura, ponerse un cinturón o prenda', 'Este verbo describe la acción de ceñirse o envolver algo alrededor de la cintura, preparándose típicamente para el trabajo o el servicio al recoger las vestiduras sueltas con un cinturón o faja. En la antigüedad, las prendas exteriores holgadas debían sujetarse para poder moverse o trabajar con libertad. En la Última Cena, Jesús «se ciñó» con una toalla antes de lavar los pies de los discípulos, un vívido símbolo de servicio. Pedro «se ciñó la ropa exterior» antes de lanzarse al agua para nadar hacia la orilla. La acción implica tanto preparación práctica como un significado simbólico de servicio y disposición.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1242', 'spa', 'pacto o testamento; un acuerdo vinculante entre Dios y su pueblo, o un documento legal de última voluntad activado por la muerte del testador', 'pacto o testamento; un acuerdo vinculante entre Dios y su pueblo, o un documento legal de última voluntad activado por la muerte del testador');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1243', 'spa', 'Diversidades, variedades o distribuciones que distinguen una cosa de otra dentro de una misma fuente', 'Este sustantivo describe diversidades, variedades o distribuciones que diferencian una cosa de otra. Pablo lo emplea tres veces en 1 Corintios 12:4-6 para hablar de las variedades de dones espirituales, ministerios y operaciones divinas, todos procedentes del mismo Dios trino. El término subraya la diversidad dentro de la unidad: la gracia divina se manifiesta en múltiples formas sin dejar de tener una sola fuente. No se trata de división que separa, sino de variedad que enriquece.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1244', 'spa', 'dividir, distribuir; repartir entre múltiples destinatarios', 'Este verbo significa separar y distribuir porciones a diferentes destinatarios. Lucas lo usa para describir cómo el padre del hijo pródigo dividió la herencia entre sus hijos (15:12), mientras que Pablo lo emplea para referirse al Espíritu distribuyendo diferentes dones a los creyentes según su voluntad (1 Corintios 12:11). El término enfatiza tanto el acto de división como la distribución resultante entre múltiples partes. Los términos españoles ''dividió'' y ''distribuyendo'', junto al francés ''diviser'', capturan este doble sentido. Resulta interesante que el mismo verbo se aplique tanto a la herencia material como a los dones espirituales, sugiriendo un rango semántico que abarca cualquier reparto entre destinatarios según algún principio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1245', 'spa', 'limpiar a fondo, despejar completamente; aventar grano o purgar impurezas', 'Este verbo compuesto intensifica ''limpiar'' con un prefijo que significa ''a través de'' o ''completamente'', sugiriendo purificación total. Juan el Bautista lo usa metafóricamente tanto en Mateo como en Lucas para describir la obra venidera del Mesías: él ''limpiará a fondo su era'', separando el trigo de la paja. La imagen agrícola del aventado—lanzar el grano al aire para que el viento quite la paja—se convierte en una poderosa imagen del juicio final y la purificación. El aspecto de ''completamente'' es crítico; esto no es una limpieza parcial sino un despeje total. El español ''limpiará'' y el francés ''nettoyer'' capturan el sentido de limpieza, mientras que el contexto exige comprender la naturaleza completa y final de esta acción purificadora.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1246', 'spa', 'refutar a fondo, confutar decisivamente; demostrar el error mediante argumentación rigurosa', 'Este verbo compuesto intensivo significa refutar completamente o demostrar de manera decisiva el error de alguien. En Acts 18:28 se describe cómo Apolos «refutaba vigorosamente» a los judíos en público, empleando las Escrituras para probar que Jesús era el Mesías. El prefijo refuerza el simple «refutar», sugiriendo una demostración exhaustiva y quizá reiterada del error ajeno. La voz media puede indicar un compromiso personal en la refutación: Apolos se entregó por entero a este combate intelectual público.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1247', 'spa', 'servir, ministrar o atender a alguien; en voz pasiva, ser servido o recibir ministerio de otros', 'servir, ministrar o atender a alguien; en voz pasiva, ser servido o recibir ministerio de otros');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1248', 'spa', 'ministerio, servicio — servicio activo a Dios y al prójimo, que abarca tanto la comisión apostólica como la atención práctica', 'ministerio, servicio — servicio activo a Dios y al prójimo, que abarca tanto la comisión apostólica como la atención práctica');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1249', 'spa', 'Siervo o ministro que sirve a otro; en las Epístolas Pastorales, diácono con cargo eclesiástico formal.', 'Siervo o ministro que sirve a otro; en las Epístolas Pastorales, diácono con cargo eclesiástico formal.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1250', 'spa', 'Doscientos; el número cardinal 200, usado para contar cantidades de personas, dinero o distancia.', 'El numeral griego para doscientos, que aparece ocho veces en el Nuevo Testamento siempre como una cantidad directa. Surge en contextos memorables: el costo del pan para alimentar a los cinco mil se calcula en 200 denarios (Marcos 6:37; Juan 6:7), la distancia desde la orilla cuando los discípulos arrastran su gran pesca es de unos 200 codos (Juan 21:8), y la escolta militar romana de Pablo incluye 200 soldados y 200 lanceros (Hechos 23:23). La traducción consistente en todas las lenguas — español ''doscientos'', francés ''deux cents'', alemán ''zweihundert'' — confirma que no hay nada idiomático aquí, sino un número preciso.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1251', 'spa', 'escuchar a fondo, dar audiencia completa; examinar un caso judicialmente de manera exhaustiva', 'Este verbo intensifica el simple ''oír'' para significar escuchar a fondo, hasta el final, o dar una audiencia judicial completa. En Hechos 23:35, el comandante romano promete a Pablo: ''Te escucharé plenamente cuando lleguen tus acusadores.'' El uso clásico incluía escuchar un caso en un tribunal o ser un discípulo que oye la instrucción completa de un maestro. El contexto legal de examen cuidadoso y exhaustivo predomina en el uso del Nuevo Testamento.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1252', 'spa', 'Separar, distinguir, discernir o dudar: abarca desde la evaluacion judicial y el establecimiento de distinciones hasta la vacilacion interna y la disp', 'Separar, distinguir, discernir o dudar: abarca desde la evaluacion judicial y el establecimiento de distinciones hasta la vacilacion interna y la disputa verbal. Formado a partir de δια- (a traves, aparte) y κρίνω (juzgar), el rango semantico de este verbo refleja el acto de separar las cosas para examinarlas. En su uso mas constructivo, significa evaluar cuidadosamente, como discernir el cuerpo del Senor (1 Co 11:29) o juzgar entre creyentes (1 Co 6:5). En la voz media-pasiva, sin embargo, se vuelve interior: el que duda esta literalmente ''dividido dentro de si mismo,'' como la persona sacudida por las olas de Santiago 1:6.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1253', 'spa', 'Discernimiento, capacidad de juzgar, distinguir o discriminar entre cosas diferentes', 'Este sustantivo designa la facultad de discernir, es decir, la capacidad de distinguir, juzgar o discriminar entre cosas diferentes, especialmente entre el bien y el mal, lo verdadero y lo falso. En Hebreos, los creyentes maduros ejercitan sus sentidos para discernir el bien del mal. Entre los dones espirituales, Pablo menciona el «discernimiento de espíritus», la habilidad sobrenatural para identificar fuentes espirituales. También puede referirse a disputas o controversias, como en Romanos 14:1, donde el juicio genera división en vez de claridad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1254', 'spa', 'impedir, prevenir, prohibir; obstruir a alguien para que no actúe', 'Este verbo significa impedir, prevenir u obstruir a alguien para que no haga algo. En Mateo 3:14, Juan el Bautista intenta ''impedir'' que Jesús sea bautizado, sintiendo que los roles deberían invertirse. El término implica una intervención activa para detener una acción. El uso clásico incluía impedir a alguien una acción específica u obstruir planes en general. Las traducciones coinciden uniformemente en resaltar la obstrucción activa como núcleo semántico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1255', 'spa', 'conversar, discutir; ser tema de conversación, propagarse como noticia (pasivo)', 'Este verbo significa conversar sobre algo o discutirlo, con la voz pasiva indicando que algo se convierte en tema de conversación generalizada. Lucas lo emplea dos veces: el embarazo milagroso de Elisabet convirtiéndose en tema de conversación en la región montañosa (1:65), y los discípulos discutiendo entre ellos después de la sanidad de Jesús en sábado (6:11). El prefijo ''dia-'' sugiere conversación que se propaga por todo o entre un grupo, no solo reflexión individual. El término captura cómo eventos significativos generan discusión comunitaria y rumor. El francés ''se répandre'' (propagarse) capta bien el sentido pasivo en Lucas 1:65, mientras que el activo en 6:11 muestra a personas conversando activamente juntas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1256', 'spa', 'Razonar, discutir o argumentar en diálogo; dirigirse a alguien o hablarle con autoridad. Un verbo que retrata vívidamente el método misionero de Pablo', 'Razonar, discutir o argumentar en diálogo; dirigirse a alguien o hablarle con autoridad. Un verbo que retrata vívidamente el método misionero de Pablo: entra en la sinagoga y ''razona'' (διαλέγομαι) a partir de las Escrituras, involucrando a su audiencia en un diálogo de ida y vuelta en lugar de una proclamación unidireccional. En Hechos 17:2, 17:17 y 18:4, el verbo lleva la fuerza de la argumentación persuasiva, la raíz de la cual derivan ''diálogo'' y ''dialéctica.'' Un uso más sutil aparece en Hebreos 12:5, donde la Escritura misma ''habla'' o ''se dirige'' al creyente, pasando del intercambio a la exhortación autoritativa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1257', 'spa', 'cesar, dejar un intervalo; detenerse o interrumpir una acción', 'Este verbo denota cesar, interrumpir o dejar un intervalo en el tiempo o en el espacio. En Lucas 7:45, Jesús dice que la mujer pecadora ''no ha cesado'' de besar sus pies desde que entró. El uso clásico incluía dejar vacíos, interrumpir acciones o mantenerse a intervalos. El aspecto temporal de cesación o acción continua (cuando se niega) es central en este término. La traducción ''cesó'' capta el sentido aspectual y durativo de detenerse o no detenerse.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1258', 'spa', 'Lengua, dialecto, idioma; el habla distintiva o vernácula de una región o pueblo determinado.', 'Designa un idioma o dialecto específico — el habla distintiva de un pueblo o región, a diferencia de la genérica ''voz'' o ''sonido''. El griego clásico distinguía διάλεκτος (habla articulada, luego variante regional) de φωνή (mero sonido o voz), y el Nuevo Testamento conserva esta precisión. Las seis apariciones se encuentran en Hechos, donde la identidad lingüística resulta crucial para la expansión del evangelio. El campo comprado con el dinero de Judas fue llamado Acéldama ''en su propia lengua'' (Hch 1:19). En Pentecostés, la multitud se asombra porque cada uno oye a los apóstoles ''en su propio dialecto'' (Hch 2:6, 8). Pablo se dirige a la multitud de Jerusalén ''en lengua hebrea'' (Hch 21:40; 22:2; 26:14), ganando así su atento silencio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1259', 'spa', 'reconciliarse; cambiar la enemistad por la paz, restaurar una relación', 'Si bien la raíz significa ''intercambiar'', esta forma media o pasiva significa específicamente reconciliarse o cambiar la enemistad por la amistad. En Mateo 5:24, Jesús ordena dejar la ofrenda y primero ''reconciliarse'' con el hermano ofendido antes de ofrecer adoración. El verbo implica un intercambio mutuo: reemplazar la hostilidad con la paz, la relación rota con la comunión restaurada. Todas las traducciones convergen en la reconciliación como núcleo teológico y relacional del significado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1260', 'spa', 'Razonar o deliberar, ya sea en debate comunal con otros o en reflexion interna privada. De la raiz λόγος (palabra, calculo) con el prefijo δια- (a tra', 'Razonar o deliberar, ya sea en debate comunal con otros o en reflexion interna privada. De la raiz λόγος (palabra, calculo) con el prefijo δια- (a traves), este verbo representa el pensamiento como un proceso de examinar un asunto a fondo. En los Evangelios aparece en dos contextos distintos: discusion grupal, donde los discipulos razonan entre si sobre las palabras de Jesus (Mt 16:7-8; Mr 8:16-17), y reflexion privada, donde un individuo pondera algo en silencio en su corazon (Lc 1:29, Maria considerando el saludo del angel; Mr 2:6, los escribas cuestionando ''en sus corazones''). Jesus a menudo percibe y expone el razonamiento privado de otros (Mr 2:8; Lc 5:22), uniendo ambos sentidos de forma dramatica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1261', 'spa', 'Pensamiento, razonamiento, deliberación; también disputa, argumento o contienda verbal entre personas. Sustantivo derivado de διαλογίζομαι (''calcular,', 'Pensamiento, razonamiento, deliberación; también disputa, argumento o contienda verbal entre personas. Sustantivo derivado de διαλογίζομαι (''calcular, razonar''), que abarca desde el razonamiento interior privado hasta la disputa verbal abierta. Jesús frecuentemente percibe los διαλογισμοί de los corazones — sus dudas ocultas, cálculos y razonamientos hostiles (Lc 5:22; 6:8). Pablo advierte que los razonamientos humanos se vuelven vanos sin Dios (Ro 1:21; 1 Co 3:20). La palabra también aparece en contextos de altercado abierto: la discusión de los discípulos sobre quién era el mayor (Lc 9:46) y la exhortación de Pablo a orar ''sin contiendas'' (1 Ti 2:8).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1262', 'spa', 'dispersar, disolver, desbandar; desintegrar una asamblea o grupo', 'Este verbo significa disolver, dispersar o desintegrar un grupo reunido. En Hechos 5:36 se describe cómo, tras la muerte de Teudas, sus seguidores ''fueron dispersados'' y quedaron en nada. El uso clásico incluía desbandar ejércitos, disolver asambleas o descomponer cosas en sus elementos. La noción de disolución, un grupo unificado que se fragmenta en individuos dispersos, es central en el significado de este término.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1263', 'spa', 'Testificar solemnemente, dar testimonio ferviente; también exhortar o advertir con urgencia solemne. Construido sobre μαρτύρομαι con el prefijo intens', 'Testificar solemnemente, dar testimonio ferviente; también exhortar o advertir con urgencia solemne. Construido sobre μαρτύρομαι con el prefijo intensificador δια-, este verbo tiene un peso que va más allá del testimonio ordinario. Denota una declaración solemne y enfática, ya sea dando testimonio sobre hechos acerca de Cristo y el evangelio, o exhortando a alguien con grave urgencia ante Dios. Lucas lo usa extensamente en Hechos para describir la proclamación apostólica: Pedro ''testificó y exhortó'' en Pentecostés (Hch 2:40), y Pablo ''testificó a los judíos que Jesús era el Cristo'' (Hch 18:5). En las Epístolas Pastorales se orienta hacia la exhortación solemne — Pablo conjura a Timoteo ''delante de Dios y de Cristo Jesús'' (2 Ti 4:1), fusionando testimonio con mandato autoritativo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1264', 'spa', 'contender vigorosamente, luchar con vehemencia; disputar o debatir con intensidad', 'Este verbo en voz media significa luchar, contender o esforzarse con ahínco, frecuentemente en el contexto de un argumento o combate intelectual. En Hechos 23:9 se describe a los fariseos que «contendían vigorosamente» durante el debate del Sanedrín sobre Pablo, aparentemente defendiéndolo. En el uso clásico se aplicaba tanto al combate físico como al debate filosófico o la defensa tenaz de una posición. Lo que caracteriza este término es la intensidad de la lucha, no un simple desacuerdo casual sino una contienda enérgica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1265', 'spa', 'Permanecer a lo largo del tiempo, continuar, persistir; de personas que perduran o estados que persisten sin cambio.', 'Compuesto de διά (''a través'') y μένω (''permanecer''), que intensifica la idea de constancia y continuidad. Zacarías ''permaneció'' mudo tras su visión en el templo (Lc 1:22). Jesús elogia a sus discípulos como quienes han ''permanecido'' con él a lo largo de sus pruebas (Lc 22:28). Pablo insiste en mantenerse firme para que la verdad del evangelio ''permanezca'' entre los gálatas (Gá 2:5). Los cielos perecerán, pero Dios ''permanece'' inmutable (He 1:11). Los burladores se mofan señalando que todas las cosas ''continúan'' como desde la creación (2 P 3:4).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1266', 'spa', 'Dividir y distribuir entre receptores, o estar dividido en desunión o conflicto interno. Derivado de la raíz que significa ''cortar en partes'', διαμερί', 'Dividir y distribuir entre receptores, o estar dividido en desunión o conflicto interno. Derivado de la raíz que significa ''cortar en partes'', διαμερίζομαι capta tanto el acto práctico de distribuir bienes como la dolorosa realidad de la división interna. En la cruz, los soldados repartieron las vestiduras de Jesús entre sí (Mt 27:35; Mr 15:24), y los primeros creyentes compartían sus posesiones libremente (Hch 2:45). Sin embargo, el mismo verbo tiene un filo más oscuro: Jesús advierte que una casa dividida contra sí misma no puede mantenerse en pie (Lc 11:17).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1267', 'spa', 'división, disensión; el acto o estado de estar dividido o separado', 'Este sustantivo designa división, partición o disensión, es decir, el estado de estar dividido. En Lucas 12:51 Jesús pregunta retóricamente si vino a traer paz o más bien «división». El término puede referirse a una separación espacial o, como en este caso, a una ruptura relacional y social. En el uso clásico abarcaba tanto la partición física como la disensión política. El concepto de separación o escisión, ya sea de objetos o de comunidades, subyace a esta palabra.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1268', 'spa', 'difundir, distribuir; ser diseminado o propagado ampliamente', 'Este verbo significa distribuir, repartir o propagar. En Hechos 4:17 las autoridades dicen que deben impedir que el mensaje «se difunda» más entre el pueblo. En el uso clásico incluía distribuir honores, dividir en porciones u ordenar. En el Nuevo Testamento se enfatiza el aspecto de propagación o diseminación, es decir, la circulación de noticias o enseñanzas a través de una población. El enfoque recae en el alcance expansivo de la información.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1269', 'spa', 'hacer señas, gesticular; comunicarse mediante gestos en lugar de palabras', 'Este verbo significa hacer señas, gesticular o comunicarse de manera no verbal. En Lucas 1:22 se describe a Zacarías, enmudecido, que «les hacía señas» para comunicarse ya que no podía hablar. En el uso clásico incluía asentir con la cabeza para comunicar algo o para evadir algo. El uso en el Nuevo Testamento se centra en la comunicación gestual y no verbal que la mudez de Zacarías hacía necesaria tras su encuentro con el ángel Gabriel.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1270', 'spa', 'pensamiento, noción, intención; el producto de la actividad mental o del razonamiento', 'Este sustantivo designa pensamientos, nociones o concepciones mentales. En Lucas 11:17 se dice que Jesús «conociendo los pensamientos de ellos» percibió sus deliberaciones e intenciones internas. En el uso clásico se distinguían los pensamientos de las palabras habladas, o se hacía referencia a significados, caprichos o fantasías. La dimensión cognitiva y mental, lo que ocurre en la mente, es central en este término. El plural suele sugerir diversos pensamientos o procesos mentales.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1271', 'spa', 'Mente, entendimiento, disposición — la facultad del discernimiento intelectual y moral; la manera de pensar de una persona. El sustantivo διάνοια se r', 'Mente, entendimiento, disposición — la facultad del discernimiento intelectual y moral; la manera de pensar de una persona. El sustantivo διάνοια se refiere a la mente como sede del entendimiento, el pensamiento y la intención moral. Su aparición más prominente es en el Gran Mandamiento: ''Amarás al Señor tu Dios con todo tu corazón, alma y mente'' (Mt 22:37; Mr 12:30; Lc 10:27), donde traduce el hebreo lēbāb y enfatiza la dimensión intelectual del amor del pacto. Más allá de esto, la palabra describe el entendimiento caído de la humanidad — ''entenebrecidos en su entendimiento'' (Ef 4:18), ''enemigos en la mente'' (Col 1:21) — y su renovación por medio de Cristo (1 Jn 5:20; He 8:10; 10:16). Primera Pedro 1:13 exhorta a los creyentes a ''ceñir los lomos de su entendimiento''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1272', 'spa', 'Abrir completamente, poner al descubierto; dicho de ojos, mentes, Escrituras y vientres que se abren, frecuentemente por acción divina.', 'Un verbo compuesto (δια + ἀνοίγω) que significa abrir de par en par o poner al descubierto, con un matiz de totalidad que el simple ''abrir'' no siempre transmite. En el NT aparece en momentos profundamente teológicos: los cielos abriéndose en el bautismo de Jesús, el vientre abriéndose para el primogénito (Lucas 2:23), los ojos abriéndose en el camino a Emaús (Lucas 24:31), la mente abriéndose para comprender las Escrituras (Lucas 24:45) y Jesús abriendo las Escrituras mismas (Lucas 24:32). La orden sanadora ''¡Efatá — sé abierto!'' (Marcos 7:34) emplea este verbo en su forma más dramática. El español distingue entre ''abrir'' (activo) y ''ser abierto'' (pasivo), reflejando la alternancia activa-pasiva presente en todos estos pasajes.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1273', 'spa', 'pasar la noche, pernoctar; permanecer durante las horas nocturnas, a menudo en alguna actividad sostenida', 'Este verbo significa pasar o permanecer durante la noche, enfatizando la duración del período nocturno. En Lucas 6:12 se describe a Jesús «pasando la noche» en oración antes de elegir a los Doce. El término se centra en el aspecto temporal de permanecer durante las horas de la noche, frecuentemente con la implicación de actividad durante ese tiempo. Tanto el uso clásico como el neotestamentario subrayan la duración y la actividad nocturna sostenida.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1274', 'spa', 'completar, terminar un viaje; llevar a cabo o concluir una travesía o tarea', 'Este verbo significa completar, llevar a cabo o finalizar, especialmente viajes o tareas. En Hechos 21:7 se describe a Pablo y sus compañeros «completando la travesía» desde Tiro hasta Tolemaida. El uso clásico incluía terminar viajes, cumplir tareas o incluso «vivir» en el sentido de completar la propia vida. El sentido central del término es llevar algo a su fin o conclusión prevista, abarcando tanto la culminación de recorridos como de cualquier empresa extendida.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1275', 'spa', 'continuamente, constantemente, en todo momento, perpetuamente', 'Expresión adverbial (escrita posteriormente como una sola palabra, y antes como dos: διὰ παντός) que significa ''continuamente'' o ''en todo momento''. La frase combina la preposición ''a través de'' con ''todo'' para crear el sentido de continuidad, es decir, algo que se extiende a lo largo de todo el tiempo sin interrupción. Describe acciones o estados que persisten de manera constante en lugar de ocurrir ocasionalmente. En contextos bíblicos, suele modificar verbos de adoración, servicio o actitud, subrayando la naturaleza perpetua e incesante de la acción.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1276', 'spa', 'Cruzar, atravesar; viajar de un lado a otro de un cuerpo de agua o una región.', 'Describe la acción de cruzar de un lado al otro, especialmente atravesar un cuerpo de agua en barca. En el griego clásico podía referirse a pasar por una ciudad o incluso ''atravesar la vida'', pero el Nuevo Testamento lo emplea sistemáticamente para el tránsito físico a través del mar de Galilea o cruces geográficos similares. Jesús cruza en barca y llega a su propia ciudad (Mt 9:1), y tras la alimentación de los cinco mil los discípulos cruzan a la tierra de Genesaret (Mt 14:34; Mr 6:53). El único uso no marítimo aparece en Lucas 16:26, donde Abraham le dice al hombre rico que un gran abismo está puesto para que nadie pueda ''cruzar'' entre el paraíso y el tormento.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1277', 'spa', 'navegar a través, cruzar por mar; completar una travesía marítima de un punto a otro', 'Este verbo significa específicamente navegar a través o cruzar una extensión de agua en barco. En Hechos 27:5 se describe que la nave de Pablo «navegó a través» del mar frente a Cilicia y Panfilia. El término enfatiza el aspecto de cruce o travesía del viaje marítimo: no se trata de simplemente navegar, sino de completar un paso de un punto a otro. El uso clásico incluía navegar por estrechos o atravesar cuerpos de agua abierta.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1278', 'spa', 'estar perturbado, molesto o muy irritado; estar agotado por labor o vejación (pasivo)', 'Este verbo originalmente significaba trabajar algo a fondo, pero en voz pasiva (como en ambas apariciones en el NT) significa estar agotado, perturbado o muy molesto. Hechos lo usa para describir a los oponentes perturbados por la enseñanza de los apóstoles: las autoridades religiosas ''muy perturbadas'' por la predicación de la resurrección (4:2), y Pablo ''muy irritado'' por el seguimiento persistente de una joven poseída por un espíritu (16:18). El término sugiere más que simple irritación—indica una vejación o perturbación significativa que compele a la acción. Los términos españoles ''disgustados'' e ''indignándose'' capturan este sentido de ser provocado al disgusto o indignación, mientras que la voz pasiva enfatiza la naturaleza involuntaria de la respuesta emocional.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1279', 'spa', 'Pasar a través de, atravesar una región o lugar, viajando de un punto a otro.', 'Verbo de tránsito que describe el movimiento a través de un lugar o región en camino hacia otro destino. En los escritos de Lucas, Jesús aparece frecuentemente pasando por pueblos y campos de grano (Lc 6:1; 13:22), mientras Pablo recorre ciudades entregando decretos (Hch 16:4). La evidencia multilingüe subraya uniformemente la idea de travesía: el español ''atravesar'', el francés ''traverser'' y el alemán ''hindurchgehen'' destacan la cualidad direccional y decidida del viaje, más que un simple caminar sin rumbo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1280', 'spa', 'διαπορέω — estar profundamente perplejo, totalmente desconcertado, sumido en confusión', 'διαπορέω intensifica el simple ἀπορέω (''estar en duda'') con el prefijo διά- (''completamente''), expresando un estado de perplejidad profunda o desconcierto total. Las cuatro apariciones neotestamentarias describen a personas confrontadas con sucesos que desafían toda explicación: Herodes queda sumamente perplejo ante los informes sobre Jesús (Lc 9:7), la multitud de Pentecostés se halla atónita y desconcertada (Hch 2:12), los oficiales del templo no saben qué pensar de la fuga de los apóstoles (Hch 5:24) y Pedro queda profundamente confundido por su visión (Hch 10:17). No se trata de una duda pasajera, sino de una genuina desorientación cognitiva ante lo inexplicable.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1281', 'spa', 'ganar comerciando, obtener beneficio mediante negocios; lograr ganancia financiera', 'Este verbo en voz media significa obtener ganancia mediante el comercio o la actividad mercantil. En Lucas 19:15 se usa en la parábola donde el noble pregunta «qué habían ganado negociando» con su dinero. El uso clásico incluía discutir a fondo, pero el sentido neotestamentario es claramente comercial: obtener beneficio mediante la actividad empresarial. El aspecto financiero y emprendedor predomina en el uso evangélico, centrándose en el resultado económico de las transacciones realizadas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1282', 'spa', 'ser herido en el corazón, enfurecerse; ser aserrado por furia o angustia', 'Este verbo vívido significa literalmente aserrar o cortar en dos, pero metafóricamente expresa ser herido en el corazón con rabia o furia. Ambas apariciones en Hechos describen reacciones violentas a la predicación apostólica: el Sanedrín siendo ''herido en el corazón'' y queriendo matar a los apóstoles (5:33), y la multitud rechinando los dientes contra Esteban antes de apedrearlo (7:54). La imagen es visceral—como si sus corazones estuvieran siendo aserrados—sugiriendo una reacción emocional intensa que pasa más allá de la simple ira hacia la rabia homicida. El español ''se enfurecían'' (se enfurecieron) captura la furia, mientras que la imagen griega de la sierra enfatiza la naturaleza penetrante y dolorosa de su ira provocada.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1283', 'spa', 'Saquear, despojar, apoderarse de bienes por la fuerza o el pillaje', 'Este verbo significa saquear, despojar o apoderarse de bienes, generalmente en un contexto de guerra, robo o incautación violenta. Jesús lo utiliza en una parábola sobre atar al hombre fuerte antes de saquear su casa: solo alguien más poderoso puede vencer a un guardián y apoderarse de sus posesiones. La imagen evoca la conquista militar o el despojo forzoso. En su aplicación espiritual, representa la victoria de Cristo sobre Satanás y el consiguiente «saqueo» de su dominio mediante la liberación de los cautivos y el avance del reino de Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1284', 'spa', 'Rasgar, desgarrar; usado especialmente para rasgarse las vestiduras como señal de duelo o indignación.', 'Describe un desgarro o rotura violenta, utilizado de manera memorable cuando el sumo sacerdote rasga sus vestiduras en el juicio de Jesús (Mt 26:65; Mc 14:63). La palabra transmite fuerza física cruda: Lucas la emplea para una red de pesca que se rompe bajo el peso de una pesca milagrosa (Lc 5:6) y para cadenas rotas por un endemoniado (Lc 8:29). En Hch 14:14, Pablo y Bernabé rasgan sus vestiduras horrorizados al ser tratados como dioses, mostrando cómo este gesto señala profunda consternación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1285', 'spa', 'explicar claramente, aclarar; dar información detallada sobre algo', 'Este verbo significa explicar o aclarar algo a fondo, haciendo que asuntos oscuros queden claros. Mateo lo usa dos veces en su Evangelio: los discípulos de Jesús pidiéndole que ''explique'' la parábola de la cizaña (13:36), y los siervos informando claramente a su amo sobre las acciones del siervo despiadado (18:31). El compuesto sugiere ''hacer claro de cabo a rabo'', eliminando ambigüedad u oscuridad. El término aparece en contextos que requieren explicación detallada o reporte claro. El español ''Explícanos'' y ''declararon'' captan directamente este sentido de aclaración, mientras el alemán ''Διασάφησον'' preserva la petición de comprensión clara.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1286', 'spa', 'extorsionar, intimidar para obtener dinero; conseguir bienes mediante amenazas o coacción violenta', 'Aunque la raíz puede significar «sacudir violentamente», este verbo desarrolló el sentido de extorsionar dinero mediante la intimidación o el acoso. En Lucas 3:14 Juan el Bautista advierte a los soldados que no «extorsionen» a la gente. El uso clásico incluía sacudir violentamente, causar confusión, intimidar o tomar dinero mediante amenazas. El enfoque neotestamentario recae en la extorsión económica mediante intimidación violenta, es decir, el abuso del poder y la posición para extraer bienes de forma coercitiva.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1287', 'spa', 'Esparcir o dispersar ampliamente; dicho de personas o rebaños separados a la fuerza, o de riquezas malgastadas por gasto imprudente.', 'Construido sobre la raíz σκορπίζω (esparcir) con el prefijo intensificador δια- (a través, por todas partes), este verbo traza imágenes vívidas de dispersión violenta. Cuando Jesús cita a Zacarías — ''heriré al pastor y las ovejas serán dispersadas'' (Mateo 26:31; Marcos 14:27) — la evidencia multilingüe es unánime: español ''dispersados'', francés ''disperser'', alemán ''zerstreut''. Pero Lucas reutiliza dos veces esta dispersión física como metáfora de la ruina económica: el hijo pródigo ''dispersó'' su herencia (Lucas 15:13) y el mayordomo injusto fue acusado de ''malgastar'' los bienes de su amo (Lucas 16:1), donde el español cambia significativamente a ''malgastando''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1288', 'spa', 'despedazar, desgarrar; ser despedazado o arrancado violentamente', 'Este verbo violento significa despedazar algo con fuerza o ser desgarrado. Marcos lo usa para el endemoniado que había roto cadenas y sido ''despedazado'' por las ataduras (5:4), mientras Hechos lo emplea para el peligro de que Pablo fuera ''despedazado'' por multitudes enfrentadas (23:10). La imagen es física y violenta—cosas o personas siendo destrozadas por fuerzas opuestas. El prefijo ''dia-'' intensifica el ''desgarrar'' básico sugiriendo separación completa o jalones en diferentes direcciones. El español ''fuera despedazado'' y el francés ''déchirer'' (desgarrar) preservan esta imagen violenta de separación o destrucción forzada.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1289', 'spa', 'Dispersar, esparcir, diseminar, especialmente referido a personas forzadas a abandonar su hogar', 'Este verbo describe la acción de dispersar o esparcir, particularmente a personas expulsadas de sus hogares o diseminadas por distintas regiones. En contextos agrícolas se refiere a esparcir semilla; en contextos militares, a tropas desbandadas. En Hechos, la persecución dispersó a los creyentes de Jerusalén por Judea y Samaria, propagando involuntariamente el evangelio más allá de su ámbito judío original. Lo que los enemigos pretendían como destrucción, Dios lo convirtió en multiplicación del mensaje. El término evoca tanto el trauma del desplazamiento como los propósitos providenciales cumplidos a través de la dispersión.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1290', 'spa', 'Diáspora, Dispersión: comunidades judías esparcidas fuera de la tierra prometida', 'La Diáspora (literalmente «dispersión» o «esparcimiento») se refiere a las comunidades judías que vivían fuera de la tierra de Israel, diseminadas entre las naciones. Esta dispersión fue resultado de diversos exilios y migraciones a lo largo de la historia. Para el siglo primero, florecían comunidades judías por todo el Mediterráneo y más allá. El término conlleva tanto una realidad geográfica como un significado teológico: el estado de dispersión representa a la vez juicio (exilio) y providencia (testimonio entre las naciones). Los autores del Nuevo Testamento dirigen cartas a creyentes judíos en la Dispersión, reconociendo sus desafíos y oportunidades particulares.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1291', 'spa', 'Mandar con severidad, dar una orden estricta; ordenar enfáticamente, especialmente exigiendo silencio u obediencia.', 'Aunque sus raíces en el griego clásico significan ''separar'' o ''distinguir'', en el Nuevo Testamento este verbo se ha reducido a un acto de habla enérgico: dar una orden estricta. Aparece casi exclusivamente en boca de Jesús, quien ordena severamente a las personas guardar silencio sobre sus milagros y su identidad mesiánica, lo que se conoce como el ''Secreto Mesiánico'' del Evangelio de Marcos (Marcos 5:43; 7:36; 8:15; 9:9). La ironía es palpable en Marcos 7:36: ''cuanto más les mandaba, tanto más lo proclamaban''. En Hechos 15:24, los apóstoles emplean el mismo verbo para aclarar lo que no mandaron, mostrando que porta autoridad incluso en el discurso eclesiástico oficial.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1292', 'spa', 'intervalo, espacio intermedio; lapso temporal o distancia espacial entre dos puntos', 'Este sustantivo designa un intervalo, espacio o brecha, ya sea de carácter temporal o espacial, entre dos puntos. En Hechos 5:7 se describe un «intervalo de unas tres horas» entre las confrontaciones de Pedro con Ananías y Safira. En el uso clásico abarcaba intervalos musicales, radios geométricos, duraciones temporales o distancias entre objetos. El concepto unificador es la separación o distancia medible en tiempo o espacio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1293', 'spa', 'Distinción, diferencia; lo que separa o marca la diferencia entre una cosa y otra', 'Este sustantivo designa una distinción o diferenciación, una diferencia marcada que separa una cosa de otra. Pablo lo emplea para subrayar la ausencia de distinción entre judío y griego en cuanto al pecado y la salvación: todos pecaron, no hay «distinción» alguna, pues ambos grupos son igualmente culpables e igualmente necesitados de gracia. El mismo Señor es Señor de todos sin hacer «distinción» entre ellos. En el ámbito musical, los instrumentos deben producir notas «distintas» para que la melodía sea comprensible. El término resalta límites, diferencias y la presencia o ausencia de factores discriminantes.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1294', 'spa', 'Pervertir, distorsionar o torcer lo recto; desviar moral o doctrinalmente.', 'Significa torcer o desviar algo de su curso correcto; en el Nuevo Testamento se usa tanto para la perversión moral como para la corrupción doctrinal activa. Jesús lo emplea como adjetivo punzante para describir a sus contemporáneos como una ''generación torcida y perversa'' (Mt 17:17; Lc 9:41), en eco de Deuteronomio 32:5. Pablo usa la forma activa para quienes intentan distorsionar la fe de otros, como cuando el mago Elimas procura ''apartar'' al procónsul de la fe (Hch 13:8). El español capta bien el rango semántico con ''perversa'' (corrupción estativa) y ''apartar'' (desvío activo).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1295', 'spa', 'Llevar a salvo a través del peligro; rescatar, preservar o sanar, enfatizando el paso seguro al otro lado del peligro.', 'Intensificado por el prefijo δια- (''a través de''), este verbo no solo salva sino que conduce a salvo al otro lado del peligro. Aparece con mayor viveza en Hechos 27-28, donde el relato del naufragio de Pablo lo usa tres veces para los pasajeros que escapan vivos a la orilla (Hechos 27:43-44; 28:1). En 1 Pedro 3:20, la familia de Noé fue ''llevada a salvo a través del agua'', ocho almas preservadas a través del diluvio. El verbo también porta un sentido de sanidad: quienes tocaron el manto de Jesús ''quedaron completamente sanos'' (Mateo 14:36). El español distingue el rescate físico (''salvados'') de la sanación (''sanados''), revelando cómo una misma palabra griega abarca tanto la preservación corporal como la restauración.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1296', 'spa', 'ordenanza, mandato; disposición o decreto autoritativo', 'Este sustantivo se refiere a una ordenanza, mandato o arreglo oficial autoritativo—algo prescrito u ordenado. Esteban habla de la ley siendo recibida ''por disposición de ángeles'' (Hechos 7:53), mientras Pablo discute la sumisión a las autoridades gobernantes, llamándolas ''ordenanzas'' de Dios (Romanos 13:2). El término sugiere arreglo o prescripción formal con autoridad vinculante. Comparte raíz con palabras para disponer u ordenar. El español ''disposiciones'' y el francés ''ordonnance'' captan el sentido de decreto o regulación autoritativa. El término puede aplicarse a ordenamientos divinos, angélicos o gubernamentales, enfatizando la naturaleza vinculante y prescrita de estos arreglos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1297', 'spa', 'edicto, decreto, ordenanza; mandato oficial con fuerza de autoridad', 'Este sustantivo designa un decreto, edicto u ordenanza oficial emitido por una autoridad. En Hebreos 11:23 se alude al «edicto» del rey que ordenaba la muerte de los niños hebreos, al cual los padres de Moisés se opusieron con valentía. El término conlleva peso legal y oficial: no se trata de una mera sugerencia, sino de un mandato autoritativo y vinculante. Los equivalentes latinos (edictum, formula) y las glosas multilingües subrayan el carácter oficial y obligatorio de tales decretos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1298', 'spa', 'turbarse profundamente, perturbarse; experimentar confusión o agitación interior intensa', 'Este verbo en voz pasiva significa estar turbado, perturbado o sumido en confusión, particularmente una agitación interior profunda. En Lucas 1:29 se describe que María «se turbó profundamente» ante el saludo del ángel. El término sugiere algo más que una leve preocupación: una perturbación o perplejidad significativa. En el uso clásico incluía sentirse perturbado por los cambios de la vida. El enfoque recae sobre la perturbación emocional y psicológica intensa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1299', 'spa', 'Mandar u ordenar; designar o nombrar para un cargo; disponer o poner en orden. El verbo griego διατάσσω transmite autoridad ejercida mediante instrucc', 'Mandar u ordenar; designar o nombrar para un cargo; disponer o poner en orden. El verbo griego διατάσσω transmite autoridad ejercida mediante instruccion estructurada: no la orden brusca de un militar, sino la disposicion deliberada de asuntos por alguien con derecho a hacerlo. Jesus ordena a sus discipulos antes de enviarlos (Mt 11:1), Pablo dispone la practica eclesial en Corinto (1 Co 11:34), y la Ley fue ordenada por medio de angeles (Ga 3:19). El prefijo δια- anade un sentido de exhaustividad: no son sugerencias casuales sino directivas integrales.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1300', 'spa', 'continuar, persistir; permanecer en un estado o seguir realizando algo de forma sostenida', 'Este verbo significa continuar, persistir o llevar algo a término. En Hechos 27:33 Pablo señala que «continuáis en ayunas» (esperando sin comer). En el uso clásico abarcaba completar períodos de tiempo, mantenerse en determinados estados o perseverar en acciones. Lo que caracteriza este término es su aspecto durativo: permanecer en una condición o persistir en una actividad a lo largo del tiempo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1301', 'spa', 'guardar cuidadosamente, atesorar; observar y preservar algo fielmente', 'Este verbo significa cuidar atentamente, guardar con seguridad o atesorar algo valioso. Lucas lo usa para María ''atesorando'' todas las palabras sobre Jesús en su corazón (2:51), mientras Hechos lo emplea para el decreto apostólico de que los creyentes gentiles deben guardarse de ciertas prácticas (15:29). El prefijo ''dia-'' sugiere minuciosidad—guardar de cabo a rabo, mantener cuidadosamente a través del tiempo. El término implica tanto custodia protectora como observancia fiel. El español ''guardaba'' (atesoraba) y el francés ''garder'' (guardar) captan este sentido de preservación cuidadosa, ya sea de recuerdos o mandatos. La palabra sugiere cuidado vigilante y continuo más que retención casual.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1302', 'spa', '¿por qué? ¿por qué razón? ¿por qué motivo?', 'Frase interrogativa (escrita como dos palabras: διὰ τί) que significa ''¿por qué?'' o ''¿por qué razón?''. La construcción pregunta literalmente ''¿a causa de qué?'', usando la preposición διὰ con el pronombre interrogativo τί. Introduce preguntas que buscan una explicación, causa o fundamento de una acción o situación. Funciona como la manera habitual de indagar sobre razones o propósitos, y aparece con frecuencia en diálogos y preguntas retóricas a lo largo de la literatura griega.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1303', 'spa', 'Hacer o establecer un pacto/testamento; asignar, disponer o legar algo a alguien.', 'Διατίθεμαι (diatithemai) es uno de los verbos de mayor carga teológica del Nuevo Testamento, compuesto de δια- (''a través'') y τίθεμαι (''colocar, disponer''), y significa literalmente disponer o arreglar algo de manera deliberada. En cinco de sus siete apariciones porta el sentido técnico y pactual de ''hacer'' o ''establecer'' un pacto — la διαθήκη de la que deriva su fuerza. Dios le dice a Israel ''haré un nuevo pacto'' (Heb 8:10; 10:16, citando a Jeremías 31), Pedro recuerda a Jerusalén ''el pacto que Dios hizo con vuestros padres'' (Hch 3:25), y el argumento de Hebreos gira en torno al hecho de que donde hay testamento debe verificarse la muerte del testador (Heb 9:16-17). Pero en la Última Cena, Jesús emplea el verbo en un sentido regio distinto: ''Yo dispongo para vosotros, como mi Padre dispuso para mí, un reino'' (Lc 22:29). Aquí el verbo pasa de hacer pactos a otorgar soberanamente: un rey concediendo dominio a sus herederos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1304', 'spa', 'Quedarse, permanecer o pasar tiempo en un lugar; residir temporalmente o demorarse.', 'En el griego clásico este verbo significaba originalmente ''frotar con fuerza'' o ''desgastar'', pero para el período helenístico había cambiado por completo a ''pasar tiempo'' o ''quedarse en un lugar''. Cada aparición en el NT se encuentra en Juan o Hechos, siempre describiendo a alguien que permanece o reside temporalmente en algún sitio durante un período. Jesús se queda con sus discípulos en la campiña judea (Juan 3:22), Pablo y Bernabé permanecen en Antioquía (Hechos 14:28; 15:35), y Herodes se retira a Cesarea (Hechos 12:19). El español ''permaneciendo'' y el francés ''séjourner'' resaltan la cualidad prolongada y asentada de la estancia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1305', 'spa', 'alimento, sustento, provisiones; los medios de nutrición y sostenimiento físico', 'Este sustantivo designa el sustento, las provisiones o los medios de sostenimiento: alimento y necesidades básicas. En 1 Timoteo 6:8 se aboga por la contentación con «alimento y vestido». En el uso clásico incluía el sustento de criaturas o los medios de subsistencia. El enfoque recae sobre las provisiones básicas necesarias para la vida, particularmente el alimento. La forma plural enfatiza la variedad de alimentos o las provisiones continuas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1306', 'spa', 'resplandecer a través, amanecer; ser transparente o translúcido (pasivo)', 'Este verbo significa resplandecer o brillar a través, con sentidos relacionados de amanecer y transparencia. Pedro exhorta a los lectores a prestar atención a la profecía hasta que el día ''amanezca'' y el lucero de la mañana se levante (2 Pedro 1:19), mientras Apocalipsis describe la calle de oro de la Nueva Jerusalén siendo ''transparente'' como vidrio (21:21). La idea raíz es luz pasando a través—ya sea el alba rompiendo la oscuridad o luz brillando a través de material claro. El rango semántico abarca aplicaciones temporales (amanecer) y materiales (transparencia) del mismo concepto central. El español ''amanezca'' y ''transparente'' muestran estas dos aplicaciones distintas, mientras el alemán ''durchsichtig'' enfatiza el ''brillar-a-través'' en el núcleo de la palabra.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1307', 'spa', 'transparente, translúcido; manifiesto, claro, conspicuo; al rojo vivo', 'Adjetivo que describe aquello que deja pasar la luz o que resulta claramente visible. En sentido físico se aplica a materiales transparentes o translúcidos, como el vidrio, a través de los cuales se puede ver. También describe algo calentado hasta ponerse al rojo vivo e incandescente. En sentido figurado se extiende a lo que es manifiesto, claro o patente, es decir, lo que no está oculto ni es oscuro. Los textos médicos lo emplean para venas que se distinguen con nitidez. Otra acepción señala lo que es conspicuo o prominente entre otros. El hilo conductor es la visibilidad: ya sea la luz atravesando algo, o algo que resulta plenamente evidente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1308', 'spa', 'Llevar a través, diferir, superar en valor; también importar o ser de interés. Un verbo griego notablemente versátil, διαφέρω literalmente significa ''', 'Llevar a través, diferir, superar en valor; también importar o ser de interés. Un verbo griego notablemente versátil, διαφέρω literalmente significa ''llevar a través'' pero se ramifica en varios usos distintos en el Nuevo Testamento. Jesús lo emplea memorablemente en el Sermón del Monte: ''¿No valéis vosotros más que las aves?'' (Mt 6:26), donde el verbo mide valor comparativo. Hechos lo usa para la difusión física de la palabra de Dios por una región (13:49) y para un barco arrastrado por una tormenta (27:27). Pablo lo despliega para la distinción teológica (1 Co 15:41, estrellas que difieren en gloria) y para el descarte retórico — ''lo que hayan sido no me importa'' (Gá 2:6).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1309', 'spa', 'escapar, huir; lograr evadirse exitosamente de un peligro o cautiverio', 'Este verbo significa escapar, huir o evadirse con éxito de una situación de peligro. En Hechos 27:42, los soldados planeaban matar a los prisioneros para que ninguno pudiera escapar nadando durante el naufragio. En el uso clásico abarcaba escapar de peligros, sobrevivir enfermedades o pasar desapercibido. El concepto central es la evasión exitosa de una amenaza, cautiverio o peligro inminente, logrando ponerse a salvo mediante la huida.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1310', 'spa', 'Difundir, divulgar ampliamente, dar a conocer por toda una región', 'Este verbo significa difundir noticias, dar a conocer algo ampliamente o divulgarlo por toda una región. En los Evangelios, a pesar de las instrucciones de Jesús de guardar silencio, las personas sanadas «difundieron la noticia» por todas partes. El término sugiere una diseminación entusiasta e incontenible: la buena nueva es demasiado maravillosa para callarla. Incluso cuando los discípulos desobedecen la orden de silencio, su desobediencia sirve al propósito mayor de dar a conocer las obras de Cristo. El verbo capta tanto la difusión literal de información como la naturaleza imparable del testimonio sobre encuentros transformadores con Jesús.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1311', 'spa', 'Destruir, corromper, arruinar; causar destrucción total o deterioro moral y físico.', 'Abarca un amplio espectro que va desde la destrucción física hasta la corrupción moral y la descomposición orgánica; el hilo conductor es la ruina completa. El prefijo δια- intensifica el verbo base φθείρω (''destruir, corromper''), produciendo un sentido de devastación total y penetrante. Pablo contrasta el cuerpo exterior que ''se va desgastando'' con la persona interior que se renueva día a día (2 Co 4:16), usando la voz pasiva para el lento deterioro de la carne mortal. En 1 Timoteo 6:5 describe mentes ''corrompidas'', moralmente arruinadas. Apocalipsis emplea la voz activa para la destrucción catastrófica: un tercio de las naves es destruido (Ap 8:9), y Dios ''destruirá a los que destruyen la tierra'' (Ap 11:18), un notable juego con las formas activa y participial del mismo verbo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1312', 'spa', 'Corrupción, descomposición, putrefacción; deterioro físico de un cuerpo, especialmente en el contexto de la teología de la resurrección.', 'Sustantivo que designa la descomposición física, la putrefacción de materia orgánica, especialmente de un cadáver humano en el sepulcro. Las seis apariciones neotestamentarias se concentran en Hechos, donde tanto Pedro como Pablo citan el Salmo 16:10 (''No permitirás que tu Santo vea corrupción'') para argumentar a favor de la resurrección de Cristo. El sermón de Pedro en Pentecostés contrasta a David, cuyo cuerpo sí vio corrupción, con Jesús, cuya carne fue preservada de la descomposición (Hch 2:27, 31). Pablo en Antioquía de Pisidia presenta el mismo argumento: Dios resucitó a Jesús antes de que su cuerpo sufriera διαφθορά, mientras que David ''durmió, fue reunido con sus padres, y vio corrupción'' (Hch 13:34-37). El término se convierte así en una expresión técnica de la apologética cristiana primitiva sobre la resurrección corporal.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1313', 'spa', 'διάφορος — diferente, diverso; en forma comparativa: superior, más excelente', 'διάφορος (de διαφέρω, ''llevar a través, diferir'') significa ''diferente'' o ''diverso'', y en su forma comparativa (διαφορώτερος) adquiere el sentido de ''más excelente, superior''. En el Nuevo Testamento abarca ambos registros. Romanos 12:6 habla de dones que difieren (διάφορα) según la gracia recibida; Hebreos 9:10 menciona diversas (διαφόροις) abluciones rituales. Pero en Hebreos 1:4 y 8:6 la forma comparativa eleva el significado: Cristo ha heredado un nombre más excelente y es mediador de un pacto superior. La palabra cubre así tanto la mera variedad como la superioridad cualitativa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1314', 'spa', 'guardar con esmero, proteger; vigilar y preservar del daño con diligencia', 'Este verbo compuesto intensivo significa guardar con esmero, vigilar de cerca o proteger diligentemente. En Lucas 4:10 se cita el Salmo 91, donde se promete que Dios guardará y protegerá a los fieles. En el uso clásico incluía custodiar ciudades, observar leyes cuidadosamente o ejercer cuidado providencial. Lo que distingue a este término no es la observación casual, sino la vigilancia protectora activa y esmerada, un cuidado que busca preservar de todo mal.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1315', 'spa', 'matar, asesinar; poner las manos violentamente sobre alguien para destruirlo (voz media)', 'Este verbo en voz media significa poner las manos violentamente sobre alguien, específicamente para matarlo o asesinarlo. Ambas ocurrencias en Hechos involucran martirio apostólico: Pedro relatando cómo los judíos ''mataron'' a Jesús (5:30), y los enemigos de Pablo intentando ''matarlo'' en el templo (26:21). La voz media sugiere acción directa y personal—poniendo las propias manos sobre la víctima. El término originalmente significaba manejar o administrar, pero en contextos hostiles se refiere específicamente a poner manos violentas sobre alguien con intención de destruirlo. El español ''matasteis'' y el francés ''mettre à mort'' capturan la naturaleza violenta y letal de esta acción.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1316', 'spa', 'separarse, partir; alejarse o dividirse de otros', 'Este verbo en voz media o pasiva significa separarse, partir o alejarse de alguien. En Lucas 9:33, Pedro habla mientras Moisés y Elías se estaban separando de Jesús después de la transfiguración. El término puede indicar una separación voluntaria o el hecho de ser separado. La acción central de este verbo es el movimiento de apartarse, creando distancia o división entre personas o cosas que estaban juntas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1317', 'spa', 'hábil para enseñar, capaz de instruir; calificado y dotado para la enseñanza', 'Este adjetivo describe a alguien apto o hábil para enseñar—una habilidad natural o desarrollada para instruir a otros. Pablo lo usa dos veces en las Epístolas Pastorales como cualificación para el liderazgo eclesial: el obispo debe ser ''apto para enseñar'' (1 Timoteo 3:2), y el siervo del Señor debe ser ''capaz de enseñar'' (2 Timoteo 2:24). El término va más allá del mero conocimiento para indicar destreza o don de enseñanza. Combina ''didáctico'' (enseñanza) con un sufijo que indica aptitud o idoneidad. Las traducciones ''apt to teach'' (inglés) y ''apto para enseñar'' (español) preservan este sentido de habilidad de enseñanza natural o cultivada como cualificación de carácter para el liderazgo ministerial.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1318', 'spa', 'Enseñado, instruido; aprendido mediante enseñanza y no de forma innata o natural', 'Este adjetivo describe lo que ha sido enseñado, aprendido mediante instrucción o transmitido por la enseñanza, en contraste con lo innato o natural. Puede aplicarse tanto a contenidos enseñados (conocimientos, habilidades) como a personas que han sido instruidas. En el Evangelio de Juan, Jesús cita a Isaías: «Todos serán enseñados por Dios», una instrucción divina prometida como rasgo del nuevo pacto. Pablo contrasta las palabras enseñadas por la sabiduría humana con las «enseñadas por el Espíritu». El término distingue entre lo adquirido mediante enseñanza y lo que podría ser evidente por sí mismo, natural o inspirado sin instrucción.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1319', 'spa', 'Enseñanza, instrucción, doctrina; el acto o contenido de la instrucción autoritativa en la iglesia.', 'Enseñanza, instrucción, doctrina; el acto o contenido de la instrucción autoritativa en la iglesia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1320', 'spa', 'Maestro, instructor — quien ensena con autoridad; titulo respetuoso para Jesus y para maestros en la iglesia', 'διδάσκαλος es la palabra griega estandar para un maestro o instructor, con connotaciones de autoridad y pericia reconocidas. En el Nuevo Testamento funciona abrumadoramente como titulo de respeto. Se aplica a Jesus mas de cuarenta veces — por discipulos, curiosos y adversarios por igual (Mt 8:19; 12:38; Mc 4:38; Jn 3:2) — y el evangelista Juan lo equipara explicitamente con el hebreo Rabbi (Jn 1:38). Pablo enumera a los ''maestros'' entre los dones fundamentales para la iglesia (1 Co 12:28; Ef 4:11), mientras que Santiago advierte que ''no os hagais maestros muchos de vosotros'' dado su juicio mas severo (Stg 3:1). El espanol ''maestro'' preserva fielmente la connotacion de autoridad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1321', 'spa', 'Ensenar o instruir; en voz pasiva, ser ensenado o recibir instruccion de otro.', 'Didasko es el verbo central del Nuevo Testamento para la ensenanza e instruccion, y describe la transmision autorizada de conocimiento, doctrina u orientacion etica. Jesus ensena en sinagogas, en laderas de montes y junto al mar (Mt 4:23; 5:2), y las multitudes se asombran porque ensena ''como quien tiene autoridad'' (Mt 7:29). Los apostoles continuan este ministerio en la iglesia primitiva. Un uso pasivo menor pero significativo destaca la recepcion de la ensenanza: Pablo insiste en que su evangelio no le fue ensenado por ningun ser humano (Ga 1:12), y a los creyentes se les recuerda lo que les fue ensenado (Ef 4:21; Col 2:7).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1322', 'spa', 'enseñanza, doctrina; el contenido o el acto de instrucción autoritativa, especialmente las enseñanzas de Jesús o los apóstoles', 'enseñanza, doctrina; el contenido o el acto de instrucción autoritativa, especialmente las enseñanzas de Jesús o los apóstoles');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1323', 'spa', 'moneda de dos dracmas; el impuesto del templo de medio siclo pagado anualmente por varones judíos', 'Este sustantivo se refiere a una moneda griega con valor de dos dracmas, equivalente al medio siclo judío. En el Nuevo Testamento aparece exclusivamente en Mateo 17:24, donde los cobradores del impuesto del templo preguntan a Pedro si Jesús paga el impuesto de ''las dos dracmas''. La pregunta se hace dos veces en el mismo versículo, dándonos ambas ocurrencias. Este impuesto era la contribución anual al templo requerida de los varones judíos basada en Éxodo 30:13. La terminología refleja la realidad multilingüe de la Judea del primer siglo, donde términos griegos de monedas se usaban para obligaciones religiosas judías. La historia del milagro resultante (Jesús dirigiendo a Pedro a encontrar el dinero del impuesto en la boca de un pez) aborda tanto la obligación como la relación única de Jesús con el templo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1324', 'spa', 'Dídimo, nombre griego que significa «gemelo», usado como designación del apóstol Tomás', 'El nombre griego Dídimo funciona como traducción o designación explicativa de Tomás, uno de los doce apóstoles. Deriva de δίδυμος, que significa «gemelo», y aparece en el Evangelio de Juan cada vez que se presenta o reintroduce a Tomás ante los lectores. Esta práctica de doble denominación refleja el contexto lingüístico mixto de la Judea del siglo I, donde coexistían nombres arameos (Tomás) y griegos. Ambos nombres significan «gemelo», de modo que se trata de una traducción directa más que de un nombre distinto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1325', 'spa', 'Dar, otorgar, conceder; en pasiva, ser dado; por extensión, poner/colocar, producir/rendir o entregar/ceder', 'δίδωμι es el verbo fundamental del Nuevo Testamento para la acción de dar, con 416 apariciones que abarcan desde la entrega del Hijo unigénito de Dios (Jn 3:16) hasta un vaso de agua fría ofrecido a un pequeño (Mt 10:42). Su peso teológico es inmenso: prácticamente toda doctrina mayor de gracia, autoridad, revelación y salvación se expresa mediante este verbo. Sin embargo, conserva extensiones concretas y terrenales: poner leyes en los corazones (Heb 8:10), la tierra que da su fruto (Mr 4:8) y el mar que entrega a sus muertos (Ap 20:13). Las formas pasivas portan especial fuerza teológica, pues «a vosotros os es dado conocer los misterios del reino» (Mt 13:11) implica un Dador divino sin nombrarlo: la clásica pasiva divina.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1326', 'spa', 'Despertar a alguien del sueño; figuradamente, avivar, agitar o excitar, ya sea la mente de una persona o la superficie del mar.', 'Verbo que transita del acto literal de despertar al sentido figurado de agitar mentes y elementos. En los relatos sinópticos de la tempestad, los discípulos aterrados despiertan a Jesús en la barca (Mr 4:39; Lc 8:24), el uso más concreto. Pero en Juan 6:18, el mismo verbo describe el mar ''agitado'' por un fuerte viento, y en 2 Pedro 1:13 y 3:1, Pedro lo emplea para avivar la mente de sus lectores hacia el recuerdo. El puente metafórico de ''despertar a alguien dormido'' a ''agitar el agua'' y ''avivar una mente'' es natural y compacto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1327', 'spa', 'salida, encrucijada, paso; vía de salida o cruce de caminos, especialmente en intersecciones', 'Este sustantivo designa una salida, paso, encrucijada o vía principal, es decir, un camino de salida o de paso. En Mateo 22:9, el rey envía a sus siervos a las encrucijadas o salidas de los caminos para invitar a los huéspedes del banquete de bodas. En el uso clásico incluía pasajes para el viento o el agua, órbitas planetarias o vías de escape. En el Nuevo Testamento se centra en las intersecciones de caminos o salidas principales de las ciudades donde transita mucha gente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1328', 'spa', 'intérprete; persona que traduce o explica el significado de una lengua a otra', 'Este sustantivo designa a un intérprete, es decir, alguien que traduce o explica el significado de un mensaje. En 1 Corintios 14:28, Pablo requiere que los que hablan en lenguas guarden silencio en la iglesia si no hay intérprete presente. Su función consiste en mediar el significado de una forma lingüística a otra, haciendo inteligible lo que de otro modo resulta incomprensible. Todas las traducciones convergen en esta función interpretativa y traductora.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1329', 'spa', 'Interpretar o explicar el significado de un discurso, profecía o Escritura; también traducir una palabra o nombre de un idioma a otro.', 'Verbo que expresa hacer accesible el significado a través de barreras, ya sea la barrera de la oscuridad o la del idioma mismo. Aparece con mayor frecuencia en el contexto de la interpretación de lenguas en la asamblea corintia (1 Co 12:30; 14:5, 13, 27), donde el habla ininteligible requiere que alguien desentrañe su sentido para la congregación. En el camino de Emaús, Jesús ''interpretó'' las Escrituras acerca de sí mismo (Lc 24:27), explicando lo que estaba oculto a plena vista. Sin embargo, en Hechos 9:36, el verbo toma un giro estrictamente lingüístico: el nombre arameo Tabita es ''traducido'' (διερμηνευομένη) como Dorcas en griego.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1330', 'spa', 'pasar a través, atravesar, recorrer; por extensión, cruzar, difundirse o traspasar', 'pasar a través, atravesar, recorrer; por extensión, cruzar, difundirse o traspasar');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1331', 'spa', 'Indagar minuciosamente, interrogar con detenimiento; buscar información mediante un cuestionamiento detallado', 'Este verbo significa indagar a fondo, interrogar insistentemente o preguntar de forma reiterada para obtener información precisa. En Hechos 10:17, los mensajeros de Cornelio habían ''indagado'' cuidadosamente para encontrar la casa de Simón. El uso clásico incluía el interrogatorio cruzado o la investigación persistente. Lo que caracteriza a este término no es una pregunta casual, sino una búsqueda decidida y meticulosa. El prefijo compuesto intensifica el simple ''preguntar'', sugiriendo una indagación minuciosa y exhaustiva.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1332', 'spa', 'De dos años de edad; relativo a la edad de dos años', 'Este adjetivo indica ''de dos años de edad'' o ''de una duración de dos años''. En Mateo 2:16 describe la matanza ordenada por Herodes de los niños ''de dos años para abajo'', según el tiempo que había averiguado de los magos. El término puede referirse tanto a la edad como a la duración temporal. En el Nuevo Testamento su uso se centra en la edad de los niños pequeños víctimas de este trágico acontecimiento histórico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1333', 'spa', 'dos años, un período de dos años; un bienio', 'Este sustantivo simplemente denota un período de dos años. Hechos lo usa dos veces para marcar duraciones significativas en el ministerio de Pablo: Félix dejando a Pablo encarcelado por ''dos años'' antes de ser sucedido (24:27), y los ''dos años'' del ministerio de Pablo en casa alquilada en Roma (28:30). El término es marcación cronológica directa sin matices simbólicos. Ambas instancias involucran períodos extendidos de relativa estabilidad—Pablo bajo arresto domiciliario o detención en lugar de persecución activa. Los períodos de dos años enmarcan fases importantes del testimonio de Pablo, aunque el Evangelio continuó avanzando a pesar de su confinamiento. El español ''dos años'' y el francés ''deux ans'' lo traducen literalmente como la simple designación temporal que es.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1334', 'spa', 'Narrar, describir en detalle, relatar; dar un relato completo de sucesos o experiencias ante una audiencia.', 'Un verbo para contar una historia a fondo: no una mención de paso, sino un relato detallado. Aparece cuando al endemoniado sanado se le dice que vaya a casa y ''cuente cuánto ha hecho Dios por él'' (Lucas 8:39), cuando los discípulos informan lo que han visto y hecho (Lucas 9:10; Marcos 9:9), y cuando testigos describen sucesos milagrosos a otros (Marcos 5:16). En Hechos, narra el encuentro de Felipe con el eunuco etíope (Hechos 8:33) y el relato de Pedro sobre la obra de Dios entre los gentiles (Hechos 9:27). El español ''contar'', el francés ''raconter'' y el alemán ''erzählen'' enfatizan la cualidad narrativa: no es un mero informe, sino el arte de relatar una experiencia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1335', 'spa', 'Narración, relato; recuento ordenado y estructurado de acontecimientos', 'Este sustantivo designa una narración, un relato o una exposición ordenada de acontecimientos. En Lucas 1:1 se refiere a los muchos que habían emprendido la tarea de componer una ''narración'' de los hechos cumplidos entre los primeros cristianos. El término enfatiza un recuento secuencial y estructurado, no apuntes sueltos sino una narración organizada con propósito. En el uso clásico incluía discursos narrativos o exposiciones de casos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1336', 'spa', 'διηνεκές — continuo, perpetuo, incesante; usado en la frase εἰς τὸ διηνεκές, ''para siempre''', 'διηνεκές significa ''continuo'' o ''perpetuo'', y en el Nuevo Testamento aparece exclusivamente en la frase fija εἰς τὸ διηνεκές (''a perpetuidad, para siempre''). Las cuatro apariciones se encuentran en Hebreos, donde el autor contrasta el sistema levítico provisional con el sacerdocio eterno de Cristo y su sacrificio de una vez para siempre. El sacerdocio según el orden de Melquisedec no tiene principio ni fin (Hb 7:3); los sacrificios repetidos de la Ley no pueden perfeccionar a nadie de manera permanente (Hb 10:1); Cristo se sienta para siempre tras una sola ofrenda (Hb 10:12); y por esa ofrenda ha perfeccionado para siempre a los santificados (Hb 10:14).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1337', 'spa', 'Entre dos mares; situado donde confluyen dos mares, formando un banco de arena o arrecife', 'Este adjetivo describe un lugar ''entre dos mares'' o donde se encuentran las corrientes de dos masas de agua. En Hechos 27:41 se describe cómo el barco de Pablo encalló en un ''lugar de dos mares'', probablemente un banco de arena o arrecife formado por la convergencia de corrientes. El uso clásico describía el Ponto Euxino o el Atlántico como divididos, o los bajíos donde confluyen los mares. El concepto central es la característica geográfica de aguas convergentes, peligrosa para la navegación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1338', 'spa', 'Penetrar, traspasar por completo; atravesar algo enteramente, en sentido físico o metafórico', 'Este verbo describe la acción de penetrar o atravesar algo por completo. En Hebreos 4:12 retrata vívidamente la palabra de Dios como más cortante que toda espada de dos filos, que penetra tan profundamente que divide el alma del espíritu. El término griego transmite un sentido de penetración total y completa: no se trata de tocar la superficie, sino de alcanzar lo más íntimo. Los usos clásicos incluyen proyectiles que alcanzan su objetivo o intervalos de tiempo que transcurren plenamente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1339', 'spa', 'Apartarse, separarse, alejarse; marcar distancia espacial o temporal entre eventos o personas', 'Este verbo compuesto (διΐστημι, de διά + ἵστημι) describe un movimiento que crea separación o intervalo. En el Nuevo Testamento aparece en contextos de intervalos temporales («pasada como una hora» en Lucas 22:59) y de alejamiento físico (Jesús apartándose de los discípulos en Lucas 24:51, marineros tomando sondeos a intervalos en Hechos 27:28). El sentido raíz de «estar aparte» se extiende naturalmente tanto a la separación espacial como al transcurso del tiempo, abarcando partida, distanciamiento y lapsos entre acontecimientos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1340', 'spa', 'insistir con fuerza, afirmar con confianza; mantener una posición con afirmación enfática (voz media)', 'Este verbo en voz media significa insistir o afirmar algo con fuerte confianza y persistencia. Lucas lo usa para la negación de Pedro: la criada ''insistía'' que él estaba con Jesús (22:59), y para la persistencia de Rode: ella ''insistía'' que Pedro estaba a la puerta (Hechos 12:15). La voz media sugiere inversión personal en la afirmación—apoyándose fuertemente en la propia convicción. El término va más allá de la simple declaración hacia la insistencia enfática y repetida a pesar de la contradicción. El verbo transmite persistencia obstinada en mantener lo que uno cree ser verdad. Curiosamente, ambas instancias lucanas involucran identificación correcta siendo inicialmente desestimada, requiriendo afirmación insistente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1341', 'spa', 'Juicio justo, veredicto recto, decisión justa y equitativa dictada conforme a normas divinas o morales', 'Sustantivo compuesto que combina ''justo'' (δίκαιος) y ''juicio'' (κρίσις), y designa un juicio inherentemente equitativo y moralmente recto. Pablo lo emplea en Romanos 2:5 para describir el día del justo juicio de Dios, cuando sus veredictos justos serán revelados. El término no se refiere a cualquier juicio, sino específicamente a uno que es éticamente íntegro y divinamente autorizado. Aparece en contextos donde se subraya la justicia de las decisiones de Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1342', 'spa', 'Justo, recto, integro; de personas en buena relacion con Dios, de acciones equitativas, y como titulo mesianico.', 'Termino moral fundamental del Nuevo Testamento que describe la conformidad con la norma de Dios. Aplicado a personas (como en Mt 1:19, donde Jose es llamado dikaios), transmite rectitud habitual y fidelidad al pacto. Aplicado a acciones (Ef 6:1), adquiere el matiz de conducta justa o apropiada. De manera mas notable aun, en Hechos 3:14, 7:52 y 22:14 se convierte en titulo cristologico —''el Justo''— donde el adjetivo cristaliza como designacion propia de Jesus en cuanto persona singularmente sin pecado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1343', 'spa', 'Justicia: rectitud moral, fidelidad al pacto y la posicion justa ante Dios que define la vida recta.', 'Dikaiosyne es una de las palabras teologicamente mas densas del Nuevo Testamento. En Mateo describe la norma superior que Jesus exige a sus seguidores (''si vuestra justicia no supera la de los escribas y fariseos'', Mt 5:20) y el objeto del hambre espiritual (''bienaventurados los que tienen hambre y sed de justicia'', Mt 5:6). Pablo la transforma en concepto soteriologico central: la justicia de Dios revelada aparte de la ley, recibida por la fe en Cristo (Ro 1:17; 3:21-22; Fil 3:9). Santiago, en cambio, vincula la justicia con obras de misericordia (Stg 2:23; 3:18).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1344', 'spa', 'Declarar o ser declarado justo; justificar, vindicar o demostrar rectitud ante Dios o los hombres.', 'Declarar o ser declarado justo; justificar, vindicar o demostrar rectitud ante Dios o los hombres.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1345', 'spa', 'Ordenanza justa, regulación o decreto; obra de justicia; acto de absolución judicial. Construido sobre la raíz δίκη (justicia), este sustantivo abarca', 'Ordenanza justa, regulación o decreto; obra de justicia; acto de absolución judicial. Construido sobre la raíz δίκη (justicia), este sustantivo abarca desde lo concreto hasta lo abstracto. En el NT se refiere con mayor frecuencia a los requisitos justos u ordenanzas de Dios: las regulaciones del culto en Hebreos 9:1, o los mandamientos en los que Zacarías e Isabel caminaban sin reproche (Lucas 1:6). Pero en Apocalipsis 19:8, el lino fino de la Esposa representa las ''obras justas'' de los santos, pasando del requisito al cumplimiento. El uso paulino en Romanos 5:16-18 es el más cargado teológicamente: un solo acto de justicia que conduce a la justificación para todos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1346', 'spa', 'Justamente, rectamente; de manera conforme a lo que es recto ante Dios y los hombres', 'Forma adverbial de δίκαιος (justo), que describe una acción realizada en conformidad con las normas divinas o morales. El ladrón arrepentido en la cruz reconoce que él y su compañero sufren «justamente» (Lucas 23:41), mientras que Pablo elogia a los tesalonicenses testificando que se comportó «rectamente» entre ellos (1 Tesalonicenses 2:10). En Tito 2:12, aparece junto a «sobriamente» y «piadosamente» como una tríada de vida cristiana. Las traducciones multilingües —español «justamente», francés «justement», alemán «gerecht»— confirman un núcleo estable de rectitud moral en la conducta.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1347', 'spa', 'justificación, vindicación; el acto de ser declarado o hecho justo', 'Este término paulino crucial denota el acto o estado de justificación—ser declarado o hecho justo delante de Dios. Pablo lo usa dos veces en Romanos: Cristo fue resucitado para nuestra ''justificación'' (4:25), y el don gratuito trae ''justificación'' que conduce a la vida (5:18). El término representa el clímax de la doctrina paulina de la salvación—el acto divino que revierte la condenación. Contrasta con ''condenación'' en 5:18, resaltando la dimensión forense. El sustantivo proviene de la misma raíz que ''justo'' y ''justificar,'' uniendo el concepto de posición correcta delante de Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1348', 'spa', 'juez, árbitro; quien emite juicio legal o resuelve disputas', 'Este sustantivo designa a un juez o árbitro—alguien autorizado para emitir decisiones legales o resolver disputas. El discurso de Esteban lo usa dos veces al relatar la historia de Moisés: el israelita que rechaza la intervención de Moisés pregunta ''¿Quién te puso por gobernante y juez sobre nosotros?'' (Hechos 7:27), y Esteban nota que este mismo Moisés a quien rechazaron, preguntando ''¿Quién te puso por gobernante y juez?'' (7:35). La duplicación enfatiza el patrón de Israel de rechazar al libertador designado por Dios. El término aparece en ambas preguntas emparejado con ''gobernante,'' sugiriendo autoridad integral sobre funciones tanto ejecutivas como judiciales.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1349', 'spa', 'justicia, castigo, retribución; el principio personificado del orden moral y sus consecuencias inevitables', 'Aunque δίκη significaba originalmente ''costumbre'' o ''modo de proceder'' en el griego clásico, para la época del Nuevo Testamento se había especializado en designar la justicia como retribución o castigo. La palabra aparece cuando la justicia divina se manifiesta en juicio: los isleños ven la víbora en la mano de Pablo como la Justicia personificada que alcanza a un homicida (Hechos 28:4), Pablo habla de quienes ''sufrirán el castigo de destrucción eterna'' (2 Tesalonicenses 1:9), y Judas describe a Sodoma padeciendo ''el castigo del fuego eterno'' (Judas 7). Se trata de justicia no como equidad, sino como consecuencia ineludible del orden moral.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1350', 'spa', 'Red de pesca — una red grande usada por los pescadores galileos, lanzada o arrastrada para atrapar peces. El sustantivo δίκτυον es el término general ', 'Red de pesca — una red grande usada por los pescadores galileos, lanzada o arrastrada para atrapar peces. El sustantivo δίκτυον es el término general para red de pesca en el Nuevo Testamento, abarcando tanto la red de lanzamiento como la red barredera. Aparece casi exclusivamente en los relatos de llamamiento y las historias de pesca milagrosa en el Mar de Galilea. Simón y Andrés estaban ''echando la red al mar'' cuando Jesús los llamó (Mt 4:18; Mr 1:16), y Jacobo y Juan estaban ''remendando sus redes'' (Mt 4:21; Mr 1:19). Lucas 5:2-6 describe redes lavadas y luego llenas hasta romperse en la pesca milagrosa, mientras que Juan 21:6-11 narra la pesca post-resurrección donde la red sostuvo 153 peces grandes sin romperse. La red se convierte así en símbolo de la misión apostólica — ''pescadores de hombres''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1351', 'spa', 'De doble palabra, que dice una cosa a una persona y otra distinta a otra; engañoso en el hablar', 'Este adjetivo significa literalmente ''de doble palabra'' y describe a quien habla con doblez, contando versiones distintas a personas diferentes. En 1 Timoteo 3:8, Pablo lo incluye entre los defectos descalificantes para los diáconos: los servidores de la iglesia no deben ser de doble lengua en su comunicación. La imagen evoca una lengua bifurcada que dice cosas contradictorias. No se trata simplemente de cambiar de opinión, sino de engañar deliberadamente mediante un discurso inconsistente destinado a manipular a distintas audiencias.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1352', 'spa', 'Por lo cual, por eso: conjuncion ilativa que extrae una conclusion firme de las premisas expuestas.', 'Dio (contraccion de di'' ho, ''a causa de lo cual'') es una conjuncion ilativa mas enfatica que el ligero oun, y aparece 53 veces en el Nuevo Testamento con especial concentracion en las epistolas paulinas. Donde oun orienta suavemente al lector, dio impulsa una conclusion decisiva: ''Por lo cual Dios tambien le exalto soberanamente'' (Fil 2:9), ''Por tanto, amados mios, huid de la idolatria'' (1 Co 10:14). Lucas la emplea en un momento cristologico clave: el anuncio del angel de que ''por lo cual lo santo que nacera sera llamado Hijo de Dios'' (Lc 1:35).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1353', 'spa', 'viajar a través, atravesar; pasar por una región en el camino', 'Este verbo significa viajar a través o atravesar una región, enfatizando el movimiento a través del territorio en lugar de hacia un solo destino. Lucas lo usa para Jesús y los Doce ''viajando a través'' de ciudades y aldeas proclamando el reino (8:1), y para Pablo y Silas ''pasando por'' Anfípolis y Apolonia en ruta a Tesalónica (Hechos 17:1). El prefijo ''dia-'' enfatiza el movimiento a través, el viaje cruzando territorio. El término sugiere ministerio o viaje itinerante, deteniéndose en varios puntos a lo largo del camino.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1354', 'spa', 'Dionisio, nombre propio que significa ''de Dioniso'' o ''seguidor de Dioniso'', un converso ateniense', 'Dionisio fue un ateniense que llegó a la fe mediante la predicación de Pablo en el Areópago (Hechos 17:34). Su nombre deriva de Dioniso, el dios griego del vino, lo cual refleja las convenciones paganas de nomenclatura en la antigua Atenas. La tradición cristiana primitiva lo identifica como el primer obispo de Atenas, aunque esto no puede verificarse solo a partir de las Escrituras. La breve mención en Hechos sugiere que era una persona de cierta relevancia social, convertida junto a Damaris y otros.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1355', 'spa', 'por lo tanto, por esta razón; conjunción inferencial fuerte que extrae conclusión de declaraciones previas', 'Esta conjunción significa ''por lo tanto'' o ''por esta razón,'' funcionando como conector inferencial fuerte que extrae conclusiones de argumentos precedentes. Pablo la usa dos veces en 1 Corintios para introducir aplicaciones prácticas de verdades doctrinales: ''Por lo tanto, si la comida hace tropezar a mi hermano...'' (8:13), y ''Por lo tanto, amados míos, huid de la idolatría'' (10:14). El término combina ''dia'' (a través/a causa de) con el pronombre relativo, creando un enlace causal fuerte—''a través de lo cual'' o ''a causa de lo cual.''');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1356', 'spa', 'Caído de Zeus, caído del cielo; dicho de objetos sagrados que se creían de origen divino celestial', 'Este raro adjetivo significa literalmente ''caído de Zeus'' y se usaba en el mundo antiguo para describir objetos, especialmente imágenes de culto, que se creían caídos del cielo como dones de los dioses. En Hechos 19:35, el secretario municipal de Éfeso lo emplea para referirse a la imagen de Artemisa albergada en su célebre templo. La afirmación de que el ídolo ''cayó del cielo'' autenticaba su origen divino según el pensamiento pagano. El término refleja la creencia religiosa antigua de que ciertos objetos sagrados tenían orígenes sobrenaturales y celestiales.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1357', 'spa', 'reforma, corrección; el enderezar las cosas o hacer mejoras', 'Este sustantivo significa corrección, reforma, o enderezar las cosas—hacer recto lo que estaba torcido. Pablo lo usa positivamente para ''reformas'' logradas mediante el gobierno de Félix (Hechos 24:2), mientras Hebreos lo usa para las limitaciones de las regulaciones del antiguo pacto efectivas solo hasta el tiempo de ''reforma'' (9:10). El término sugiere mejora o corrección sistemática de lo que estaba mal o deficiente. El uso en Hebreos es particularmente significativo, marcando la era del nuevo pacto como el tiempo cuando ocurre la corrección y reordenamiento divinos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1358', 'spa', 'διορύσσω — cavar a través de, perforar un muro; irrumpir en una casa excavando la pared de adobe', 'Διορύσσω (de διά, ''a través'', y ὀρύσσω, ''cavar'') significa abrir un boquete cavando, especialmente a través de los muros de adobe o tierra de las casas del antiguo Cercano Oriente. Las cuatro apariciones neotestamentarias se refieren al robo mediante perforación de paredes. Jesús advierte contra acumular tesoros donde los ladrones ''perforan'' y roban (Mt 6:19-20), y en las parábolas del amo vigilante, el ladrón habría ''irrumpido'' si el dueño no hubiera velado (Mt 24:43; Lc 12:39). Los equivalentes en español —perforar, horadar— reflejan el acto físico de excavar un muro, imagen vívida que resulta ajena al lector moderno desconocedor de la construcción en adobe.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1359', 'spa', 'Los Dióscuros (Cástor y Pólux), hijos gemelos de Zeus, dioses patronos de los marineros, constelación de Géminis', 'Los Dióscuros, literalmente ''hijos de Zeus'', eran los gemelos divinos Cástor y Pólux (en griego, Polideuces), nacidos de Leda. En la religión grecorromana eran dioses patronos de los navegantes, de quienes se creía que protegían los barcos y se manifestaban como el fuego de San Telmo durante las tormentas. Hechos 28:11 los menciona como mascarón de proa del navío alejandrino que transportó a Pablo desde Malta hasta Italia. Los barcos solían llevar imágenes de deidades protectoras en sus proas, y los Dióscuros eran especialmente populares en las embarcaciones del Mediterráneo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1360', 'spa', 'Porque, puesto que, por la razón de que; ocasionalmente inferencial: ''por lo cual, por eso.''', 'Porque, puesto que, por la razón de que; ocasionalmente inferencial: ''por lo cual, por eso.''');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1361', 'spa', 'Diotrefes, nombre propio que significa ''nutrido por Zeus''; líder eclesiástico primitivo que amaba la preeminencia', 'Diótrefes aparece únicamente en 3 Juan 9 como un líder de la iglesia que se opuso a la autoridad del apóstol Juan y se negó a recibir a los misioneros itinerantes. Su nombre significa ''nutrido/protegido por Zeus'', un nombre teofórico griego común. Juan lo critica por su afán de preeminencia, por difundir chismes maliciosos contra los apóstoles y por excomulgar a quienes mostraban hospitalidad hacia los enviados de Juan. Representa las luchas de poder en la iglesia primitiva y el peligro del autoritarismo desvinculado de la enseñanza apostólica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1362', 'spa', 'διπλοῦς — doble, dos veces más; duplicado en cantidad, grado o medida', 'Διπλοῦς significa ''doble'' o ''dos veces más'', indicando algo multiplicado por dos en cantidad, grado o severidad. En el Nuevo Testamento posee tanto fuerza literal como moral intensificada. Jesús declara que los escribas y fariseos hacen de un prosélito ''el doble de hijo de la Gehena'' que ellos mismos (Mt 23:15), un demoledor recurso retórico de duplicación. Pablo exhorta a reconocer a los ancianos que gobiernan bien con ''doble honor'' (1 Ti 5:17). Y en Apocalipsis 18:6 se le retribuye a Babilonia el doble por sus pecados. El término abarca así desde la duplicación numérica hasta la retribución moral intensificada.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1363', 'spa', 'Doblar, multiplicar por dos, repetir el doble; devolver el doble de una cantidad', 'Este verbo significa hacer doble o multiplicar por dos. En Apocalipsis 18:6 aparece en la orden relativa a Babilonia: ''Devolvédle el doble conforme a sus obras.'' El acto de duplicar representa una justicia proporcional: ella recibe el doble de lo que infligió, subrayando la plenitud de la retribución divina. El griego clásico lo empleaba para duplicar cantidades, plegar telas por la mitad o saldar deudas con intereses. En el Nuevo Testamento transmite la idea de un juicio completo y multiplicado, acorde con la magnitud de la transgresión.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1364', 'spa', 'Adverbio: dos veces; en forma compuesta: dos miríadas (veinte mil).', 'El adverbio griego δίς significa simplemente ''dos veces'' y aparece en momentos de repetición significativa a lo largo del Nuevo Testamento. Pedro oye al gallo cantar ''dos veces'' como Jesús lo predijo (Mr 14:30, 72), el fariseo se jacta de ayunar ''dos veces por semana'' (Lc 18:12), y Pablo relata haber enviado ayuda a Tesalónica ''dos veces'' (Fil 4:16; 1 Ts 2:18). Un solo uso especializado en Apocalipsis 9:16 conserva la palabra en forma compuesta como parte de δισμυριάδες μυριάδων (''dos miríadas de miríadas''), produciendo una cifra de caballería inmensa. Aquí, la misma raíz que en otros pasajes cuenta hasta dos, de pronto escala a aritmética cósmica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1365', 'spa', 'dudar, vacilar en incertidumbre; estar dividido en mente o titubear', 'Este verbo significa dudar o vacilar, sugiriendo división o titubeo en la mente. La conexión de raíz con ''dos veces'' o ''doble'' implica ser jalado en dos direcciones. Mateo lo usa dos veces: Jesús preguntándole a Pedro por qué ''dudó'' mientras se hundía (14:31), y notando que algunos discípulos ''dudaron'' incluso al ver a Cristo resucitado (28:17). Ambos contextos involucran desafíos de fe en momentos sobrenaturales—caminar sobre el agua y la aparición de la resurrección. El término captura la división interna entre fe y temor, creencia e incertidumbre. El español ''dudaste'' y el francés ''douter'' transmiten directamente este vacilar entre alternativas, este estar de dos mentes.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1366', 'spa', 'de doble filo; que describe espadas o armas con filos cortantes en ambos lados', 'El adjetivo δίστομος (literalmente ''de dos bocas'', de δίς + στόμα) describe armas afiladas por ambos lados. En el uso bíblico aparece exclusivamente en contextos metafóricos sobre la palabra de Dios como arma: más cortante que toda espada de dos filos en Hebreos 4:12, y saliendo de la boca de Cristo en Apocalipsis 1:16 y 2:12. La imagen enfatiza un poder penetrante y discernidor: una hoja que corta desde cualquier dirección, sin dejar nada sin examinar.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1367', 'spa', 'Dos mil, el número 2.000; una cantidad específica en el rango de los miles', 'Término numérico sencillo que significa dos mil. Marcos 5:13 lo emplea para describir el tamaño de la piara de cerdos en la que Jesús permitió entrar a los demonios: unos dos mil cerdos se precipitaron por el despeñadero al mar y se ahogaron. La cifra concreta subraya la magnitud tanto de la posesión demoníaca (los demonios se llamaban ''Legión'') como de la pérdida económica para los porqueros. Los adjetivos numerales griegos como este formaban parte del vocabulario estándar para el conteo y la medición.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1368', 'spa', 'Colar, filtrar con cuidado, eliminar partículas pequeñas pasándolas por un filtro; metáfora de escrupulosidad', 'Este verbo significa colar o filtrar minuciosamente, eliminando partículas diminutas de un líquido. Jesús lo emplea de forma memorable en Mateo 23:24 cuando acusa a los escribas y fariseos de ''colar el mosquito pero tragarse el camello'': ser meticulosamente escrupulosos con asuntos rituales menores mientras ignoran fallos morales gravísimos. La imagen proviene de las prácticas de elaboración de vino y purificación de agua, donde se filtraban mosquitos y otras impurezas pequeñas. El griego clásico lo usaba para el filtrado cuidadoso de vino u otros líquidos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1369', 'spa', 'Dividir en dos, separar, enemistar; provocar división o discordia entre personas', 'Este verbo significa fundamentalmente dividir algo en dos partes o partir por la mitad. Mateo 10:35 lo emplea en la solemne profecía de Jesús de que Él vino ''a poner al hombre contra su padre'': su mensaje crearía división incluso dentro de las familias. El término puede describir una división física o, metafóricamente, separación relacional y conflicto. El griego clásico lo usaba para cortar cosas literalmente en dos o para referirse a la separación del mediodía (el día ''partido''). En el Nuevo Testamento enfatiza el impacto social divisivo de la lealtad a Cristo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1370', 'spa', 'disensión, división; estar separados en desacuerdo o conflicto', 'Este sustantivo denota disensión, división o estar separados—particularmente en contextos de discordia comunitaria. Pablo advierte contra aquellos que causan ''divisiones'' contrarias a la enseñanza apostólica (Romanos 16:17) y enumera ''disensiones'' entre las obras de la carne (Gálatas 5:20). El término sugiere no meramente desacuerdo sino un activo estar-separados que fractura la unidad comunitaria. Combina ''dicha'' (en dos partes) con ''stasis'' (estar de pie), literalmente ''estar en dos''—una comunidad jalada en facciones. El español ''disensiones'' y ''divisiones'', junto con el alemán ''Zwietracht'' (discordia), capturan este sentido de unidad fracturada. Pablo presenta consistentemente tal división como contraria a la vida comunitaria guiada por el Espíritu.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1371', 'spa', 'cortar en dos, separar completamente; castigar con máxima severidad', 'Este verbo gráfico literalmente significa cortar en dos o bisecar, pero metafóricamente indica castigo o juicio severo. Jesús lo usa idénticamente en Mateo y Lucas para advertir que al siervo infiel ''lo cortará en dos'' y lo pondrá con los hipócritas (Mateo 24:51) o incrédulos (Lucas 12:46). Ya sea desmembramiento literal o metáfora de severidad máxima, el término transmite juicio decisivo e irreversible. La imaginería impactante subraya la seriedad de la infidelidad en la mayordomía. El francés ''couper en deux'' y el español ''lo cortará en dos'' preservan la imaginería literal de cortar, aunque el contexto puede sugerir que esto representa el juicio más severo posible en lugar de describir un método de ejecución.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1372', 'spa', 'Tener sed, estar sediento: experimentar la necesidad fisica de agua o un anhelo metaforico de plenitud espiritual. Διψάω capta tanto la sensacion fisi', 'Tener sed, estar sediento: experimentar la necesidad fisica de agua o un anhelo metaforico de plenitud espiritual. Διψάω capta tanto la sensacion fisica cruda de la sed como una profunda metafora espiritual. En el plano literal, Jesus se identifica con el sediento en la parabola de las ovejas y los cabritos: ''tuve sed y me disteis de beber'' (Mt 25:35), y clama ''Tengo sed'' desde la cruz (Jn 19:28). En el plano metaforico, las Bienaventuranzas prometen que quienes ''tienen hambre y sed de justicia'' seran saciados (Mt 5:6), y Jesus declara que quien beba del agua que el da ''nunca mas tendra sed'' (Jn 4:14; 6:35). Apocalipsis cierra con este doble registro: ''el que tenga sed, venga'' (Ap 21:6; 22:17).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1373', 'spa', 'Sed, la condición física de necesitar agua; anhelo de beber, deshidratación', 'Sustantivo que designa la experiencia física de la sed: la necesidad corporal de agua. Pablo lo incluye en 2 Corintios 11:27 entre los padecimientos de su ministerio apostólico: el hambre y la sed formaban parte de las privaciones que soportó por causa del evangelio. Aunque las Escrituras también emplean la sed como metáfora del anhelo espiritual (como hace Jesús en Juan 4), esta ocurrencia particular se refiere a la carencia física literal. El término aparece tanto en el griego clásico como en la Septuaginta para esta experiencia humana universal.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1374', 'spa', 'de doble ánimo, vacilante; tener alma dividida o lealtades conflictivas', 'Este adjetivo vívido literalmente significa ''de doble alma'' o tener dos mentes, describiendo a alguien inestable o vacilante en sus compromisos. Santiago lo usa dos veces: llamando al hombre de doble ánimo inestable en todos sus caminos (1:8), e instando a los pecadores a purificar sus corazones ya que son ''de doble ánimo'' (4:8). El término captura la división interna y la consecuente inestabilidad—intentar servir a dos señores o mantener lealtades conflictivas. La construcción ''di-psychos'' sugiere un alma dividida entre lealtades competidoras. El español ''de doble ánimo'' y el alemán ''zweifelhaft'' (dudoso) intentan capturar esta división interna que produce falta de fiabilidad e inestabilidad en toda conducta.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1375', 'spa', 'Persecución, hostigamiento sistemático u opresión por causa de la fe. Denota acción hostil dirigida contra individuos o comunidades debido a su compro', 'Persecución, hostigamiento sistemático u opresión por causa de la fe. Denota acción hostil dirigida contra individuos o comunidades debido a su compromiso religioso, desde el ostracismo social hasta la violencia organizada. Jesús advierte que la persecución acompañará a la palabra sembrada en terreno pedregoso (Mateo 13:21; Marcos 4:17) y la promete como compañera inseparable del discipulado (Marcos 10:30). Hechos 8:1 registra la gran persecución que dispersó a la iglesia de Jerusalén tras la muerte de Esteban. Pablo cataloga la persecución entre sus sufrimientos apostólicos (Romanos 8:35; 2 Corintios 12:10; 2 Timoteo 3:11), tratándola como algo normativo para el testimonio fiel.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1376', 'spa', 'Perseguidor, quien acosa a otros con intención de dañarlos, hostigador de los fieles', 'Este sustantivo designa a alguien que persigue a otros para hacerles daño: un perseguidor o cazador de personas. Pablo lo emplea refiriéndose a sí mismo en 1 Timoteo 1:13, confesando que antes de su conversión era «blasfemo, perseguidor y agresor violento» contra la iglesia. El término deriva del verbo «perseguir» o «dar caza», con connotaciones de acechar a una presa. La autodescripción de Pablo resalta la magnitud de la misericordia divina: incluso un perseguidor violento de cristianos pudo ser transformado en apóstol de Cristo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1377', 'spa', 'Perseguir u hostigar; persecución hostil de personas, o búsqueda ardiente de virtudes como la paz.', 'Perseguir u hostigar; persecución hostil de personas, o búsqueda ardiente de virtudes como la paz.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1378', 'spa', 'Decreto, ordenanza o edicto oficial; también una regulación doctrinal o disposición legal', 'Abarca tanto edictos civiles como ordenanzas religiosas. César Augusto emite un «decreto» para que todo el mundo sea empadronado (Lucas 2:1), y los judíos de Tesalónica acusan a Pablo de actuar contra los «decretos» del César (Hechos 17:7). Sin embargo, la misma palabra designa también las decisiones apostólicas entregadas a las iglesias (Hechos 16:4) y las ordenanzas legales judías que Cristo abolió en su carne (Efesios 2:15; Colosenses 2:14). Esta amplitud se refleja en las distintas lenguas: el español emplea tanto «decreto» como «ordenanzas», el francés «décret» y el alemán «Satzung» (estatuto).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1379', 'spa', 'Someterse a reglas o decretos, sujetarse a ordenanzas, aceptar regulaciones impuestas', 'Este verbo en voz pasiva significa someterse a decretos, ordenanzas o regulaciones. Pablo lo utiliza en Colosenses 2:20 para interpelar a los colosenses: si habéis muerto con Cristo a los principios elementales del mundo, ¿por qué os sometéis a decretos como si aún vivierais en el mundo? El término subraya la sumisión voluntaria a normas impuestas externamente. El griego clásico lo empleaba para establecer decretos o, en voz pasiva, para estar gobernado por ellos. Pablo cuestiona por qué los creyentes regresarían a una religión legalista tras haber experimentado la libertad en Cristo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1380', 'spa', 'Pensar, suponer; parecer o aparentar; impersonalmente, parecer bien o decidir; ser estimado o reputado.', 'Este versatil verbo griego transita fluidamente entre el mundo interior del pensamiento y el mundo exterior de la apariencia. Cuando Jesus pregunta ''?Que pensais?'' (Mt 17:25; 22:42), la palabra invita a una deliberacion genuina. Cuando algo ''parece'' de cierta manera (Mt 18:12), el enfasis se desplaza a la percepcion y la impresion. Lucas emplea la construccion impersonal ''me parecio bien'' (Lc 1:3) para introducir su Evangelio, y el concilio de Jerusalen usa la misma forma para su decision comunitaria (Hch 15:25, 28). Pablo extiende aun mas el sentido en Galatas 2, donde ''los que parecian ser algo'' son sopesados y hallados genuinamente autoritativos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1381', 'spa', 'Probar, examinar, poner a prueba; discernir o interpretar; aprobar como digno tras un escrutinio.', 'Probar, examinar, poner a prueba; discernir o interpretar; aprobar como digno tras un escrutinio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1382', 'spa', 'Prueba, carácter probado u ordalia; el proceso de poner a prueba y la cualidad comprobada que resulta de soportar la tribulación.', 'Un sustantivo ricamente estratificado que transita desde el acto de probar hasta su resultado. En Romanos 5:4, Pablo traza una cadena: la tribulación produce paciencia, y la paciencia produce δοκιμή, un carácter probado y forjado en la batalla. En otros pasajes denota la prueba concreta o evidencia que valida una afirmación, como cuando Pablo busca ''la prueba de vuestra obediencia'' (2 Corintios 2:9). También puede nombrar la prueba misma, como en la ''gran tribulación'' de las iglesias de Macedonia (2 Corintios 8:2). Tanto el español como el francés vierten los tres sentidos con una sola palabra (''prueba'', ''épreuve''), mostrando cuán estrechamente ligados están el acto de probar y la cualidad que este produce.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1383', 'spa', 'prueba, ensayo; un medio de probar o examinar algo', 'Este sustantivo se refiere a una prueba o ensayo que demuestra autenticidad—un medio de examen que revela verdadera calidad. Santiago habla de la ''prueba'' de la fe produciendo perseverancia (1:3), mientras Pedro describe la ''autenticidad'' de la fe siendo más preciosa que oro probado (1 Pedro 1:7). El término enfatiza no la prueba misma sino la función probatoria o examinadora de la prueba. Comparte raíces con palabras para aprobado, probado, genuino. El concepto es metalúrgico—como el fuego prueba el oro, las pruebas prueban la fe. El español ''prueba'' y el alemán ''Bewaehrung'' (comprobación/confirmación) capturan este sentido de una prueba que revela y valida calidad genuina a través del proceso de examen.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1384', 'spa', 'Aprobado, probado y hallado genuino; considerado digno de confianza tras ser examinado o puesto a prueba.', 'Describe a alguien o algo que ha sido sometido a prueba y ha resultado genuino, confiable o aceptable. En el mundo antiguo, el termino se aplicaba a las monedas verificadas como autenticas (''de curso legal''), y este trasfondo metalurgico permea su uso neotestamentario. Pablo elogia a Apeles como ''aprobado en Cristo'' (Rom 16:10) y advierte que las divisiones existen precisamente para que ''se manifiesten los que son aprobados'' (1 Cor 11:19). El concepto subraya un proceso de verificacion mediante prueba, no una mera opinion humana.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1385', 'spa', 'Viga, madero grande; pieza gruesa de madera usada figuradamente para una falta grave en uno mismo.', 'Un madero estructural de gran tamano, una viga maestra usada en techumbres o construcciones, que Jesus emplea en una de sus ilustraciones mas vividas y memorables. En el Sermon del Monte (Mat 7:3-5) y su paralelo lucano (Luc 6:41-42), contrasta la dokos (''viga'') en el ojo propio con la karphos (''pajilla'' o ''astilla'') en el ojo del projimo. La imagen hiperbolica es deliberadamente absurda: como puedes ofrecer sacar una diminuta astilla del ojo ajeno cuando una viga entera sobresale del tuyo? La metafora ensena el autoexamen antes de la critica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1386', 'spa', 'Engañoso, astuto, traicionero; caracterizado por la astucia y la intención de engañar', 'Adjetivo que significa astuto, engañoso o traicionero, describiendo a quien opera mediante la astucia y el engaño en lugar de la honestidad. Pablo lo emplea en 2 Corintios 11:13 para describir a los falsos apóstoles como «obreros engañosos» que se disfrazan de apóstoles de Cristo. El griego clásico lo aplicaba a personas traicioneras, maquinaciones astutas e incluso a deidades como Hermes y Afrodita, conocidas por sus artimañas. El término subraya el engaño deliberado y calculado, diseñado para desorientar a otros en beneficio propio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1387', 'spa', 'Obrar con engaño, actuar traicioneramente, usar artimañas; comportarse de forma fraudulenta con otros', 'Este verbo significa actuar traicioneramente o tratar con engaño a alguien. Romanos 3:13 cita el Salmo 5:9 dentro del catálogo paulino de la pecaminosidad universal humana: «con sus lenguas engañaban». El término enfatiza un comportamiento engañoso continuo y un trato traicionero. La Septuaginta lo emplea para describir el actuar con dolo o traicionar la confianza. El griego clásico lo utilizaba de manera similar para la conducta traicionera. El uso de Pablo subraya la corrupción moral de la humanidad: el habla misma se convierte en instrumento de engaño y traición.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1388', 'spa', 'Engaño, astucia, doblez: decepción deliberada o traición empleada para confundir o causar daño. El sustantivo δόλος denota engaño deliberado o astucia', 'Engaño, astucia, doblez: decepción deliberada o traición empleada para confundir o causar daño. El sustantivo δόλος denota engaño deliberado o astucia utilizada para perjudicar a alguien. Los sumos sacerdotes buscan arrestar a Jesús ''con engaño'' (Mateo 26:4; Marcos 14:1), y Elimas es denunciado como ''lleno de todo engaño'' (Hechos 13:10). En sentido positivo, su ausencia marca integridad: Natanael es uno ''en quien no hay engaño'' (Juan 1:47), y Cristo no tenía ''engaño en su boca'' (1 Pedro 2:22). La palabra también aparece en listas de vicios (Marcos 7:22; Romanos 1:29; 1 Pedro 2:1).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1389', 'spa', 'Adulterar, falsificar, corromper mezclando; manejar con engano o manipular deshonestamente', 'Este verbo significa adulterar, corromper o manejar algo con engano, como un comerciante que mezcla materiales inferiores en un producto para defraudar a sus clientes. Pablo lo emplea en 2 Corintios 4:2 al renunciar a ''adulterar la palabra de Dios'', es decir, se niega a corromper o manipular el mensaje divino para beneficio personal. En el griego clasico se usaba para adulterar vino, alear metales con sustancias mas baratas o disfrazar cosas de manera enganosa. Pablo contrasta tal corrupcion con la proclamacion abierta y honesta de la verdad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1390', 'spa', 'δόμα — don, regalo; algo dado o concedido, con énfasis en la cosa otorgada', 'Δόμα designa un don o regalo, derivado del verbo δίδωμι (''dar''). Está emparentado con δῶρον (G1435) y δώρημα (G1434), pero δόμα tiende a subrayar el objeto concreto entregado más que el acto de dar. Jesús argumenta de menor a mayor: si los padres terrenales saben dar buenos dones (δόματα) a sus hijos, cuánto más el Padre celestial dará cosas buenas —o el Espíritu Santo— a quienes se lo pidan (Mt 7:11; Lc 11:13). Pablo cita el Salmo 68:18 en Efesios 4:8: el Cristo ascendido ''dio dones (δόματα) a los hombres''. En Filipenses 4:17 Pablo emplea el término para referirse a la ofrenda económica de los filipenses.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1391', 'spa', 'Gloria, esplendor, majestad radiante; la manifestación visible de la excelencia y el honor divinos', 'En el griego clásico, δόξα significaba simplemente «opinión» o «reputación», pero la Septuaginta la transformó en la traducción estándar del hebreo כָּבוֹד — la presencia pesada y luminosa de Dios. Para el Nuevo Testamento, δόξα carga todo el peso de la radiancia divina: la gloria shekiná que llenaba el templo, el esplendor revelado en la Transfiguración (Mt 17:2) y la magnificencia eterna a la que los creyentes están destinados (Ro 8:18). Cada idioma principal la traduce con un término dominante único — «gloria», «gloire», «Herrlichkeit», «महिमा» — reflejando su peso semántico unitario.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1392', 'spa', 'Glorificar o alabar; atribuir gloria a Dios activamente, o ser glorificado y recibir honor divino, especialmente en la teologia juanina.', 'Verbo teologicamente central con dos movimientos complementarios: los seres humanos glorificando a Dios, y Dios siendo glorificado. En su sentido activo, describe la respuesta de alabanza: las multitudes glorifican a Dios tras las sanaciones (Mt 9:8; Mr 2:12; Lc 2:20) y los creyentes honran a Dios mediante una conducta recta (Mt 5:16). El sentido pasivo y divino-pasivo adquiere especial protagonismo en el Evangelio de Juan, donde Jesus habla de ser glorificado por medio de la cruz (Jn 12:16, 23; 13:31-32) y de la glorificacion mutua entre el Padre y el Hijo (Jn 17:1, 4-5).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1393', 'spa', 'Dorcas (nombre propio): una discípula en Jope conocida por sus buenas obras y caridad, también llamada Tabita', 'Dorcas es el nombre griego (que significa ''gacela'') de una discípula en Jope a quien Pedro resucitó de entre los muertos. Hechos 9 relata su historia, usando tanto su nombre arameo Tabita como su nombre griego Dorcas. Era conocida por sus buenas obras y actos de caridad, particularmente por confeccionar vestidos para las viudas. Su muerte ocasionó gran luto, y la resurrección que Pedro realizó se hizo ampliamente conocida, llevando a muchos a creer. Ambos versículos (9:36, 9:39) usan la forma griega de su nombre, aunque la narración indica que la comunidad la conocía por ambos nombres, reflejando la naturaleza bilingüe del judaísmo de la diáspora.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1394', 'spa', 'dar, el acto de dar; una dádiva o donación', 'Este sustantivo denota el acto de dar o una dádiva dada, enfocándose en la acción de dar más que en el objeto dado. Pablo lo usa para describir el patrón de dar y recibir de los filipenses en la asociación del evangelio (4:15), mientras que Santiago contrasta el dar variable con la bondad inmutable de Dios (1:17). El término enfatiza la acción dinámica de otorgar. Comparte raíces con ''didomi'' (dar), convirtiéndolo en la forma nominal de la acción misma de dar. Curiosamente, Santiago lo usa en paralelo con ''buen don'', distinguiendo el acto de dar (dosis) del don dado (dōrēma), aunque algunas traducciones difuminan esta distinción. El uso en Filipenses enfatiza el intercambio recíproco en el ministerio del evangelio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1395', 'spa', 'Dador, el que da, donante; persona caracterizada por la generosidad y la entrega', 'Sustantivo sencillo que significa ''dador'', es decir, aquel que da o dona. Pablo lo utiliza en 2 Corintios 9:7 en su celebre declaracion: ''Dios ama al dador alegre.'' El termino no se limita al acto de dar, sino que destaca a la persona caracterizada por la generosidad. Es una forma griega tardia relacionada con el verbo ''dar''. El punto de Pablo es que Dios no valora la cantidad entregada sino la actitud del corazon: la disposicion gozosa antes que la obligacion a reganadientes. La disposicion del dador importa mas que el tamano del don.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1396', 'spa', 'Esclavizar, someter, disciplinar severamente; ejercer control estricto sobre algo o alguien', 'Este verbo significa esclavizar, sojuzgar o someter a disciplina rigurosa, literalmente tratar algo como esclavo. Pablo lo emplea en 1 Corintios 9:27 al describir su autodisciplina: ''Disciplino mi cuerpo y lo pongo en servidumbre.'' La imagen es la de un atleta o luchador que ejerce control riguroso sobre sus impulsos fisicos para alcanzar una meta. En el griego clasico se usaba para reducir a alguien a la esclavitud o ejercer dominio severo. Pablo lo aplica al autodominio voluntario, tratando su cuerpo como esclavo para asegurar la eficacia de su ministerio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1397', 'spa', 'Esclavitud, servidumbre; la condición de estar esclavizado, ya sea física, espiritual o existencialmente', 'Designa el estado de estar en cautiverio o servidumbre, usado exclusivamente en las epístolas para describir la esclavitud espiritual y existencial. Pablo contrasta el «espíritu de esclavitud» con el «espíritu de adopción» (Romanos 8:15) y declara que la creación misma gime bajo la «servidumbre de la corrupción» (Romanos 8:21). La correspondencia a los Gálatas intensifica la metáfora: el antiguo pacto engendra hijos «para esclavitud» (Gálatas 4:24), y los creyentes no deben someterse de nuevo a un «yugo de esclavitud» (Gálatas 5:1). Las traducciones en diversas lenguas —español «esclavitud», francés «esclavage/servitude», alemán «Knechtschaft»— captan el peso de la subyugación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1398', 'spa', 'Servir o estar sujeto a; ser esclavizado, vivir en servidumbre.', 'Servir o estar sujeto a; ser esclavizado, vivir en servidumbre.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1399', 'spa', 'esclava, sierva; mujer en servidumbre, frecuentemente usada como autodesignación ante Dios', 'La forma femenina δούλη corresponde a δοῦλος y designa a una mujer en servidumbre. En el Nuevo Testamento aparece de manera notable en contextos de autodesignación religiosa: María se llama a sí misma ''sierva del Señor'' (Lucas 1:38, 48), y Pedro cita la profecía de Joel sobre el derramamiento del Espíritu de Dios sobre las ''siervas'' (Hechos 2:18). Aunque el término clásico podía referirse a la esclavitud como propiedad, el uso bíblico lo eleva para expresar sumisión voluntaria al servicio de Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1400', 'spa', 'esclavo, siervo; persona nacida en esclavitud o sujeta a la voluntad de otro', 'Sustantivo que designa a alguien en estado de servidumbre o esclavitud. Originalmente distinguía a quienes nacían esclavos de quienes eran esclavizados después, pero terminó funcionando como el término general para esclavo o siervo, en contraste con el amo (δεσπότης). Los escritores griegos lo aplicaban a los persas y a otros pueblos bajo gobiernos despóticos, y metafóricamente a quienes estaban esclavizados por las pasiones, el dinero o los apetitos. La forma femenina (δούλη) designa a una esclava. Como adjetivo, describe un carácter o acciones serviles. El término abarca la esclavitud legal, la sujeción política y la servidumbre metafórica a poderes distintos de un amo literal.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1401', 'spa', 'Esclavo, siervo — persona sujeta al servicio de un amo; usado literalmente de esclavos y figuradamente del servicio devoto a Dios o a Cristo', 'δοῦλος designa a una persona que pertenece a otra: un esclavo o siervo. A diferencia del español «sirviente», que puede implicar empleo voluntario, δοῦλος en el mundo grecorromano significaba propiedad legal — una persona sin derechos autónomos. El Nuevo Testamento emplea este término contundente en ambas direcciones: Jesús cuenta parábolas con esclavos domésticos literales (Mt 18:23-35; Lc 17:7-10), y Pablo, Santiago, Pedro y Judas se identifican cada uno como δοῦλος de Cristo (Ro 1:1; Fil 1:1; Stg 1:1; 2 P 1:1; Jud 1). La paradoja es deliberada: la sumisión total al Señor divino se presenta como la libertad más alta.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1402', 'spa', 'Esclavizar, someter a servidumbre; en voz pasiva, ser esclavizado o sometido — referido a servidumbre literal, espiritual y relacional.', 'Verbo que significa reducir a alguien a la esclavitud o hallarse en estado de servidumbre. En sus usos activos describe la sujeción forzosa de una persona por otra, como en Hechos 7:6 donde una nación extranjera esclavizará a los descendientes de Abraham, o en 2 Pedro 2:19 donde falsos maestros esclavizan a otros mediante promesas corruptas. Pablo lo aplica de manera llamativa a sí mismo en 1 Corintios 9:19, diciendo que se hizo esclavo de todos por causa del evangelio. Las formas pasivas describen el estado resultante: creyentes antes esclavizados al pecado (Ro 6:18, 22) o los gálatas sometidos a los rudimentos elementales (Gá 4:3).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1403', 'spa', 'recepción, banquete; un festín o reunión festiva para recibir invitados', 'Este sustantivo significa una recepción o festín, particularmente un banquete dado para honrar o recibir a alguien. Lucas lo usa dos veces: Leví haciendo ''un gran banquete'' para Jesús (5:29), y Jesús instruyendo a su anfitrión a invitar a los pobres cuando dé ''un banquete'' (14:13). Ambos contextos involucran hospitalidad de banquete donde los invitados son recibidos y honrados. El término comparte raíces con ''dechomai'' (recibir), enfatizando el aspecto receptivo y acogedor de la reunión festiva. El español ''banquete'' y el francés ''banquet'' traducen directamente esto como el ambiente de comida festiva. El uso de Lucas destaca las prácticas de compañerismo de mesa de Jesús y su enseñanza sobre hospitalidad inclusiva que invierte las expectativas sociales.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1404', 'spa', 'Dragón, gran serpiente — una criatura reptiliana temible que simboliza a Satanás en la visión apocalíptica. δράκων en el griego clásico denotaba una g', 'Dragón, gran serpiente — una criatura reptiliana temible que simboliza a Satanás en la visión apocalíptica. δράκων en el griego clásico denotaba una gran serpiente o dragón mítico, probablemente derivado de δέρκομαι (''mirar con agudeza''), refiriéndose a la mirada penetrante de la criatura. Las 13 apariciones neotestamentarias ocurren todas en Apocalipsis, donde el dragón es explícitamente identificado como ''la serpiente antigua, que se llama Diablo y Satanás'' (Ap 12:9, 20:2). La visión apocalíptica de Juan retrata un gran dragón rojo con siete cabezas y diez cuernos (Ap 12:3) librando una guerra cósmica contra la mujer y su descendencia. La imaginería del dragón hunde sus raíces en el Antiguo Testamento — Leviatán, Rahab, el monstruo marino — reinterpretados como símbolo definitivo de la oposición satánica a los propósitos de Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1405', 'spa', 'Agarrar, asir con la mano, atrapar; tomar firmemente en su puno', 'Este verbo en voz media significa agarrar o asir algo con la mano, tomar con firmeza. En 1 Corintios 3:19, Pablo cita Job 5:13: Dios ''atrapa a los sabios en su propia astucia.'' La imagen es la de Dios que agarra a los intrigantes astutos como quien sujeta a un adversario. En el griego clasico se usaba para aferrar punados de algo o agarrar a alguien por la garganta. El uso neotestamentario subraya el poder de Dios para capturar y frustrar a quienes confian en su propia astucia en lugar de en la sabiduria divina.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1406', 'spa', 'dracma, moneda griega de plata equivalente al salario de un día, usada en la parábola de la moneda perdida', 'La dracma era una moneda de plata del sistema monetario griego, aproximadamente equivalente al denario romano y representativa de un jornal obrero. En el Nuevo Testamento aparece exclusivamente en la parábola de la moneda perdida (Lucas 15:8-9), donde una mujer busca con empeño una de sus diez dracmas. El valor de la moneda, significativo pero no extravagante, ilustra el punto de la parábola: lo que a otros les parece pequeño es precioso para quien lo posee, así como cada pecador perdido importa a Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1407', 'spa', 'Hoz; hoja curva para segar, usada literalmente de la cosecha de grano y figuradamente de la siega divina del fin de los tiempos.', 'Herramienta curva de corte empleada para segar el grano, que aparece tanto en un registro parabólico como en uno apocalíptico. En Marcos 4:29, Jesús dice que cuando el grano está maduro, el labrador mete la hoz porque ha llegado la siega, una imagen agrícola cotidiana. Pero en Apocalipsis 14:14-19, la hoz se convierte en instrumento de juicio cósmico: el Hijo del Hombre y los ángeles lanzan sus hoces para segar la cosecha de la tierra y recoger las uvas para el lagar de la ira de Dios. A pesar del salto de la parábola pastoral a la visión apocalíptica, el referente subyacente sigue siendo el mismo implemento agrícola.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1408', 'spa', 'carrera, curso; camino a recorrer, metafóricamente la misión de vida o servicio encomendado', 'Tomado del contexto atlético donde δρόμος significaba una carrera a pie o el trayecto mismo, el término adquiere un rico sentido metafórico en las reflexiones de Pablo sobre su ministerio. Habla de ''terminar la carrera'' o ''completar el curso'' para describir la fiel culminación de su llamado apostólico. La imagen combina la idea de un camino definido, un esfuerzo sostenido y una meta final, aspectos todos apropiados para describir el ministerio cristiano o la vida misma como un recorrido con propósito de principio a fin.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1409', 'spa', 'Drusila, nombre personal romano; esposa del gobernador Felix, hija de Herodes Agripa I', 'Drusila fue la esposa del procurador romano Felix, presente cuando Pablo razono acerca de la fe en Cristo (Hechos 24:24). Era hija de Herodes Agripa I y bisnieta de Herodes el Grande. Su nombre es latino, procedente de la familia Druso. Historicamente, dejo a su primer esposo para casarse con Felix, un escandalo documentado por Josefo. La mencion que Lucas hace de ella sugiere que tanto ella como Felix escucharon la presentacion del evangelio por parte de Pablo, aunque su respuesta fue posponer la conversacion por temor.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1410', 'spa', 'Poder, ser capaz; como verbo «puede/podía»; como sustantivo, «el poderoso» o «el que tiene poder»', 'δύναμαι es la raíz del inglés «dynamic» y «dynamite», y sus 210 ocurrencias neotestamentarias vibran con preguntas de capacidad y poder. «¿Pueden estas piedras convertirse en pan?» (Mt 4:3). «Nadie puede servir a dos señores» (Mt 6:24). «Para Dios todo es posible» (Mt 19:26). En un puñado de pasajes, el participio pasa de verbal a sustantivado, describiendo a alguien — frecuentemente Dios — como «el Poderoso» (Ro 15:14; 2 Ti 1:12). El español «puede», el francés «pouvoir» y el alemán «kann» captan el sentido modal básico, pero el uso sustantivado de «el poderoso» revela la profundidad teológica latente en este verbo cotidiano.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1411', 'spa', 'Poder, fuerza, obra milagrosa, potencia cósmica, capacidad o significado — desde la fuerza inherente de Dios hasta milagros concretos y seres espirituales', 'δύναμις es la palabra por excelencia del Nuevo Testamento para designar el poder, origen del inglés «dynamic» y «dynamite». Pero su alcance va mucho más allá de la fuerza bruta. En singular nombra el poder crudo e inherente de Dios o de su Espíritu (Lc 1:35; Hch 1:8), mientras que en plural se bifurca en dos direcciones notablemente distintas: obras milagrosas concretas («los milagros» que Jesús realizaba) y seres espirituales cósmicos («las potencias» que no pueden separarnos del amor de Dios). Pablo incluso la emplea una vez para el «significado» de un sonido hablado (1 Co 14:11), y la parábola de los talentos la usa para la «capacidad» práctica proporcionada a cada siervo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1412', 'spa', 'ser fortalecido, capacitado; recibir o ejercer poder (pasivo)', 'Este verbo significa ser fortalecido o capacitado, recibir poder habilitante para una tarea. Pablo lo usa para ser ''fortalecido con todo poder'' según el poder de Dios para la paciencia (Colosenses 1:11), y para los fieles que por fe ''fueron fortalecidos'' de la debilidad (Hebreos 11:34). La voz pasiva enfatiza recibir poder de una fuente externa en lugar de fuerza autogenerada. El término se construye sobre ''dynamis'' (poder), creando un verbo para el acto dinámico de empoderar o ser empoderado. El español ''fortalecidos'' y el francés ''fortifier'' capturan este sentido de recibir fuerza, ser hecho poderoso para desafíos más allá de la capacidad natural.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1413', 'spa', 'gobernante, soberano, poderoso; persona de gran autoridad o poder, desde funcionarios de corte hasta la majestad divina', 'El sustantivo δυνάστης (de δύναμαι, ''poder, ser capaz'') designa a quien ejerce poder o dominio, abarcando desde funcionarios de la corte hasta gobernantes supremos. En el uso bíblico cubre desde un alto oficial etíope hasta la soberanía absoluta de Dios. El término enfatiza el poder efectivo más que la posición meramente formal: se trata de personas capaces de transformar realidades, ya sea mediante autoridad política, fuerza militar u omnipotencia divina.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1414', 'spa', 'ser capaz, ser poderoso; expresar capacidad, potencia o habilitación para actuar', 'Esta forma verbal de δυνατός funciona de manera similar al más frecuente δύναμαι, pero con un énfasis algo mayor en la capacidad o el poder inherente. Aparece en contextos paulinos que resaltan la habilitación divina: Dios puede hacer que los creyentes permanezcan firmes, hacer que la gracia abunde y obrar poderosamente mediante Cristo. La palabra se centra en la capacidad y la potencia, no en el mero permiso: se trata de tener el poder para lograr algo, no solo la autorización para intentarlo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1415', 'spa', 'Posible (impersonal: ''es posible''); poderoso, fuerte (de personas/hechos); capaz (con infinitivo).', 'Posible (impersonal: ''es posible''); poderoso, fuerte (de personas/hechos); capaz (con infinitivo).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1416', 'spa', 'ponerse, descender (del sol); hundirse debajo del horizonte', 'Este verbo describe la puesta del sol o su descenso debajo del horizonte. Ambas instancias en los Evangelios marcan la transición del día a la tarde cuando la gente traía a los enfermos a Jesús para sanación: en Marcos ''cuando el sol se puso'' (1:32), y en Lucas ''mientras el sol se ponía'' (4:40). El marcador temporal es significativo porque las restricciones del sábado terminaban al atardecer, permitiendo a las multitudes cargar a sus enfermos. El verbo captura el movimiento celestial diario que estructura el cálculo del tiempo antiguo. El español ''se puso'' y el francés ''se coucher'' (acostarse/ponerse) aplican naturalmente este verbo al descenso diario del sol debajo del horizonte.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1417', 'spa', 'Dos — el numeral cardinal para un par, usado atributiva y sustantivamente en todo el Nuevo Testamento', 'δύο es el numeral cardinal griego «dos», que aparece 137 veces en el Nuevo Testamento en todos los casos y géneros. Funciona tanto como cuantificador simple — «dos hermanos» (Mt 4:18), «dos gorriones» (Mt 10:29) — como número teológicamente significativo: dos testigos establecen un testimonio (Mt 18:16; Ap 11:3), no se puede servir a dos señores (Mt 6:24), y «donde están dos o tres reunidos» Cristo está presente (Mt 18:20). La palabra es morfológicamente indeclinable en muchos contextos, como ya lo era en el ático clásico. El español «dos», el francés «deux» y el alemán «zwei» lo traducen de manera directa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1418', 'spa', 'prefijo que significa des-, mal-, difícil o desafortunado; crea significados negativos o intensificados', 'Prefijo inseparable que se opone a εὖ- (bien, bueno) y añade nociones de dificultad, desgracia o maldad a las palabras que modifica. Puede destruir el sentido positivo de un vocablo o intensificar su carga negativa. Llama la atención que pueda unirse incluso a palabras que ya expresan negación, creando enfáticos dobles negativos. El uso poético lo explota para contrastes marcados, como en «Paris el mal-Paris» o «boda que es mala boda». Ante ciertos grupos consonánticos (στ, σθ, σπ, σφ, σχ), la sigma final se pierde. El prefijo tiene cognados en sánscrito y otras lenguas indoeuropeas, todos con fuerza negativa similar.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1419', 'spa', 'difícil de llevar, oneroso, intolerable', 'Este adjetivo griego describe cargas que son penosas o intolerables de llevar. Jesús lo usa en Mateo 23:4 para criticar a los líderes religiosos que atan cargas pesadas sobre los hombros de las personas, y Lucas 11:46 hace eco de esta condena. La palabra enfatiza no solo el peso sino la dificultad opresiva de sobrellevar tales cargas, ya sean físicas o espirituales.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1420', 'spa', 'Disentería, inflamación intestinal severa que causa diarrea sanguinolenta; una condición médica específica', 'Término médico que designa la disentería, una inflamación grave de los intestinos que provoca diarrea con sangre, fiebre y dolor abdominal. En Hechos 28:8 se describe al padre de Publio postrado con fiebre y disentería, hasta que Pablo lo sanó en la isla de Malta. El vocablo era empleado en los escritos médicos clásicos de Hipócrates y otros autores para referirse a esta enfermedad específica. Lucas, el evangelista y médico, utiliza con precisión la terminología médica de su época. La sanidad demuestra el poder de Cristo sobre la enfermedad y abrió puertas para el ministerio en la isla.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1421', 'spa', 'Difícil de interpretar, arduo de explicar; que no se comprende ni se comunica fácilmente', 'Este adjetivo significa difícil de interpretar, explicar o expresar, algo que resulta arduo de comunicar con claridad. En Hebreos 5:11 el autor lo emplea al señalar que ciertas enseñanzas sobre Melquisedec son «difíciles de explicar» porque los lectores se han vuelto tardos para oír. El griego clásico también lo usaba para referirse a cosas difíciles de describir o interpretar. La dificultad no reside en el tema en sí, sino en comunicarlo a un público poco preparado o desatento. La frustración del autor apunta a la inmadurez espiritual de los lectores, no a la oscuridad inherente de la doctrina.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1422', 'spa', 'Difícil, arduo de lograr, trabajoso; que presenta desafíos u obstáculos', 'Este adjetivo significa difícil, arduo o trabajoso, y describe algo que presenta desafíos considerables. En Marcos 10:24, Jesús lo emplea al decir: «¡Cuán difícil les es entrar en el reino de Dios a los que confían en las riquezas!». El griego clásico lo utilizaba para referirse a personas difíciles de complacer, situaciones problemáticas o tareas arduas de realizar. El término enfatiza una dificultad objetiva, no una imposibilidad. La enseñanza de Jesús aborda el genuino desafío que la riqueza plantea al discipulado: las riquezas incitan a la autosuficiencia, lo que hace psicológicamente difícil depender de Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1423', 'spa', 'con dificultad, difícilmente; describiendo algo logrado solo mediante gran esfuerzo o lucha', 'El adverbio δυσκόλως (de δύσκολος, ''difícil de complacer'') describe acciones que solo se consiguen con enorme dificultad. En los Evangelios Sinópticos aparece en la solemne advertencia de Jesús sobre la riqueza y el reino: es extremadamente difícil que los ricos entren en el reino de Dios. La palabra transmite un sentido de casi imposibilidad, algo que solo se logra mediante un esfuerzo o una intervención extraordinaria, si acaso se logra.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1424', 'spa', 'Occidente, poniente, la puesta del sol; la direccion donde el sol se oculta, con uso geografico y simbolico.', 'Derivado del verbo dyo (''ponerse, hundirse''), este sustantivo designa el punto cardinal donde el sol se pone: el occidente. Casi siempre aparece en plural (dysmai) y se empareja con anatolai (''oriente'') para abarcar toda la extension de la tierra. Jesus declara que muchos vendran ''del oriente y del occidente'' a sentarse a la mesa con Abraham, Isaac y Jacob en el reino (Mat 8:11; Luc 13:29), usando este merismo para expresar universalidad. La analogia del relampago que ''sale del oriente y resplandece hasta el occidente'' (Mat 24:27) subraya la visibilidad inconfundible de la venida del Hijo del Hombre. En Lucas 12:54, una nube que sube ''del occidente'' anuncia lluvia, reflejando el clima de Palestina donde la humedad proviene del Mediterraneo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1425', 'spa', 'Difícil de entender, arduo de comprender intelectualmente; que no se capta con facilidad', 'Este adjetivo describe algo intelectualmente difícil de captar o comprender. En 2 Pedro 3:16, Pedro reconoce que algunas cosas en las cartas de Pablo son «difíciles de entender», las cuales los indoctos e inconstantes tuercen para su propia perdición. El griego clásico lo empleaba para referirse a cosas difíciles de comprender. La franca admisión de Pedro valida el desafío intelectual que presenta cierta enseñanza bíblica, al tiempo que advierte contra usar esa dificultad como pretexto para distorsionarla. La dificultad exige estudio diligente, no una revisión que acomode el texto a nuestras preferencias.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1426', 'spa', 'ser difamado, experimentar mala reputación o calumnia', 'Esta forma participial describe la experiencia de ser objeto de calumnia o difamación. Pablo la usa dos veces para describir la experiencia ministerial: en 1 Corintios 4:13 en medio de la persecución, y en 2 Corintios 6:8 como uno de los contrastes en una serie de paradojas. El término captura no solo el abuso verbal sino el daño a la reputación que acompaña al ministerio fiel en un mundo hostil.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1427', 'spa', 'Doce: el numero cardinal, usado frecuentemente para designar las doce tribus de Israel o los doce apostoles.', 'Dodeka es el numero cardinal griego doce, que aparece en todos los generos y casos. En el Nuevo Testamento funciona tanto como simple numeral (una mujer enferma durante doce anos, Mt 9:20; doce canastas de sobras, Mt 14:20) como designacion teologica cargada de significado. ''Los Doce'' se convirtio en titulo casi propio para el circulo intimo de los discipulos de Jesus (Mt 10:1-5; 1 Co 15:5), evocando deliberadamente las doce tribus de Israel y senalando la restauracion escatologica. Su simplicidad semantica contrasta con su enorme peso simbolico segun el contexto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1428', 'spa', 'Duodécimo, el número ordinal que indica la posición doce en una secuencia', 'El número ordinal «duodécimo» indica la posición número doce en una secuencia. En Apocalipsis 21:20 se emplea para describir el duodécimo fundamento de la Nueva Jerusalén, adornado con amatista. Se trata de vocabulario numérico directo, sin un significado teológico especial más allá del simbolismo de plenitud que el número doce porta en la numerología bíblica (doce tribus, doce apóstoles). Los números ordinales griegos funcionan de manera equivalente a los españoles para indicar posición u orden dentro de una serie.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1429', 'spa', 'Las doce tribus, designación colectiva de las tribus de Israel como un pueblo unificado', 'Adjetivo compuesto que significa ''de doce tribus'', usado como sustantivo para referirse al pueblo colectivo de Israel. En Hechos 26:7, Pablo habla de ''nuestras doce tribus'' que sirven a Dios con fervor día y noche, esperando alcanzar la promesa. Aunque diez tribus habían sido dispersadas siglos antes, el judaísmo mantuvo el concepto de la nación unificada de doce tribus. El término subraya la identidad corporativa de Israel como pueblo del pacto de Dios. El uso que Pablo hace del término muestra que la esperanza de la resurrección era fundamentalmente judía, no una religión nueva.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1430', 'spa', 'Azotea, terrado, techo plano de un edificio; la terraza accesible tipica de la arquitectura del Cercano Oriente antiguo.', 'Se refiere al techo plano o azotea de una vivienda tipica del Cercano Oriente antiguo, que servia como espacio al aire libre para actividades cotidianas, oracion y proclamacion publica. En Lucas 5:19, unos amigos bajan a un paralitico por el tejado para llevarlo ante Jesus. En las advertencias escatologicas de Mateo 24:17 y Marcos 13:15, la urgencia se transmite diciendole al que este en la azotea que no baje a recoger nada de su casa. Jesus ordena a sus discipulos proclamar desde las azoteas lo que han oido en secreto (Mat 10:27; Luc 12:3). El termino designa un referente concreto y arquitectonico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1431', 'spa', 'Don, regalo gratuito — una dádiva inmerecida, especialmente el don gracioso de Dios del Espíritu o la salvación. El sustantivo δωρεά (dorea) designa u', 'Don, regalo gratuito — una dádiva inmerecida, especialmente el don gracioso de Dios del Espíritu o la salvación. El sustantivo δωρεά (dorea) designa un don otorgado libremente, refiriéndose casi exclusivamente a la generosa dádiva de Dios. Jesús le habla a la mujer samaritana del ''don de Dios'' (Juan 4:10). Pedro promete ''el don del Espíritu Santo'' en Pentecostés (Hechos 2:38), y el derramamiento del Espíritu sobre los gentiles asombra a los creyentes judíos (Hechos 10:45). Simón el Mago es reprendido por pensar que el don de Dios podría comprarse con dinero (Hechos 8:20). El argumento de Pablo en Romanos 5:15-17 gira en torno al ''don gratuito'' de la gracia que supera la transgresión de Adán.');